const AF={x:0,z:-33500,hx:760,hz:2450,H:45,B:2300,L:3200,W:60};
// usable rolling area (inside the plateau, away from the blended edge)
const inAF=(x,z)=>Math.abs(x-AF.x)<AF.hx-200&&Math.abs(z-AF.z)<AF.hz-200;
