 {const Hf=new Float32Array(p.count);for(let i=0;i<p.count;i++)Hf[i]=p.getY(i);THF.n=SEG+1;THF.cell=SZ/SEG;THF.o=-SZ/2;THF.h=Hf;let mx=0;for(let i=0;i<Hf.length;i++)if(Hf[i]>mx)mx=Hf[i];THF.top=mx+20;}
