const WXP={ // coverage drives how many cumulus clusters are drawn; strat = stratus deck coverage; fog = exp2 density; gray/dark shade the cloud; ov dims the sun
  CLEAR:    {cu:14, base:0,    strat:0,   alt:4200,th:0,   fog:1.25e-5,gray:0,  dark:0,  ov:0,   turb:.02,rain:0,  name:'CLEAR'},
  SCATTERED:{cu:110,base:0,    strat:0,   alt:4200,th:0,   fog:1.5e-5, gray:0,  dark:0,  ov:.06, turb:.12,rain:0,  name:'SCATTERED'},
  BROKEN:   {cu:300,base:-250, strat:.5,  alt:4300,th:500, fog:2.4e-5, gray:.22,dark:.1, ov:.38, turb:.3, rain:0,  name:'BROKEN'},
  OVERCAST: {cu:120,base:-650, strat:1,   alt:3300,th:900, fog:3.4e-5, gray:.55,dark:.35,ov:.8,  turb:.38,rain:.25,name:'OVERCAST'},
  STORM:    {cu:200,base:-900, strat:1,   alt:2500,th:2600,fog:7.5e-5, gray:.9, dark:1,  ov:1,   turb:.95,rain:1,  name:'STORM'}};
