    const sd=window.STRAT;if(sd){sd.visible=this.P.strat>0;sd.material.uniforms.uCov.value=this.P.strat;sd.material.uniforms.uAlt.value=this.P.alt;sd.material.uniforms.uDark.value=this.P.dark;}
