    const dim=1-ov*(this.wx==='STORM'?.62:.3)*(.4+.6*dayK);
    const top=des(K.top,ov*.85).map(v=>v*dim),mid=des(K.mid,ov*.9).map(v=>v*dim),hor=des(K.hor,ov*.8).map(v=>v*dim);
    const cg=[.43,.45,.49],ci=this.inK,L=Math.max(.12,dim*(.25+.75*dayK)+.1*night);
    const fT=this.mix(top,[cg[0]*L,cg[1]*L,cg[2]*L],ci),fM=this.mix(mid,[cg[0]*L,cg[1]*L,cg[2]*L],ci),fH=this.mix(hor,[cg[0]*L*1.05,cg[1]*L*1.05,cg[2]*L*1.05],ci);
    const fb=fl*.55;
    SKY.material.uniforms.top.value.setRGB(fT[0]+fb,fT[1]+fb,fT[2]+fb*1.1);SKY.material.uniforms.mid.value.setRGB(fM[0]+fb,fM[1]+fb,fM[2]+fb*1.1);
    FOGC.setRGB(fH[0]+fb,fH[1]+fb,fH[2]+fb*1.1);
    SKY.material.uniforms.uGlow.value.setRGB(K.sun[0],K.sun[1]*.95,K.sun[2]*.9);SKY.material.uniforms.uSunK.value=clamp((1-ov*1.15)*dayK+(1-ov)*.0,0,1)*clamp((el+1.5)/3,0,1);
    // lights
    const sunI=K.sunI*(1-ov*.8);
    if(el>-3){sun.color.setRGB(K.sun[0],K.sun[1],K.sun[2]);sun.intensity=sunI;sun.position.copy(SUNDIR);}
    else{const az=Math.atan2(SUNDIR.x,-SUNDIR.z)+Math.PI;sun.position.set(Math.sin(az)*.82,.58,-Math.cos(az)*.82);sun.color.setRGB(.55,.66,.95);sun.intensity=.2*night*(1-ov*.5);}
