  vertexShader:'attribute float size;attribute vec4 col;varying vec4 vC;uniform float uScale;void main(){vC=col;vec4 mv=modelViewMatrix*vec4(position,1.);gl_PointSize=clamp(size*uScale/-mv.z,'+(additive?'1.5':'0.')+',256.);gl_Position=projectionMatrix*mv;}',
