    for(const c of ck.cur.glass){if(c.clone().sub(ckCam.position).dot(cf)<=.05)return null;const p=c.clone().project(ckCam);out.push({x:(p.x*.5+.5)*W,y:(-p.y*.5+.5)*H});}
