    for(let s=Math.floor((v-60)/10)*10;s<=v+80;s+=10){if(s<0)continue;const e=EC-(s-v)/K;if(e>E0||e<E1)continue;const big=s%50===0;
      seg(A,e,A-(big?.8:.42),e);if(big)T(String(s),A-1.05,e,'right');}
