function drawWsWin(P){const c=wsC.getContext('2d');c.fillStyle='#120603';c.fillRect(0,0,220,52);if(!P)return;const w=game.wsel;
  c.fillStyle='#ff8a2a';c.font='700 18px "B612 Mono",monospace';c.textAlign='left';c.textBaseline='middle';
  c.fillText(`${w==='GUN'?'GSh-30':SN[w]} ×${w==='GUN'?P.gun.ammo:P.count(w)}`,10,16);c.fillText(game.arm?'MASTER ARM ON':'MASTER ARM OFF',10,38);}

/* ---- F-16A panel: round steam gauges, stores control panel (orange LED), HSI, static placards ---- */
const VG={};['as','alt','vvi','aoa','g','clk','rpm','ftit','noz','oil','fuel'].forEach(k=>VG[k]=mk(192,192));
const hsiC=mk(256,256),hsi=hsiC.getContext('2d'),scpC=mk(320,256),scp=scpC.getContext('2d');
