function vdial(c,o){const x=96,y=96,r=90,cv=c.canvas;
  const N=v=>(o.a0+(o.a1-o.a0)*clamp((v-o.min)/(o.max-o.min),0,1)-90)*D2R;
  const q=v=>v==null||!isFinite(v)?'':Math.round(N(v)*360),key=q(o.v)+'|'+q(o.v2)+'|'+q(o.vmax)+'|'+(o.win==null?'':o.win)+'|'+gfx.panelK;
  const sig=gfx.panelK+':'+o.min+','+o.max+','+o.a0+','+o.a1+','+o.major+','+(o.minor||0)+','+(o.lbl||'')+','+o.fmt(o.min)+','+o.fmt(o.max);
  if(cv._vk===key&&cv._vsig===sig)return;cv._vk=key;cv._ver=(cv._ver||0)+1;
  if(cv._vsig!==sig||!cv._vbg){cv._vsig=sig;const bg=cv._vbg||(cv._vbg=mk(192,192)),b=bg.getContext('2d');b.setTransform(1,0,0,1,0,0);
    b.fillStyle='#0a0b0b';b.fillRect(0,0,192,192);b.strokeStyle='#33383b';b.lineWidth=6;b.beginPath();b.arc(x,y,r-3,0,7);b.stroke();
    b.strokeStyle=b.fillStyle='#eef0ea';b.textAlign='center';b.textBaseline='middle';
    // all the minor ticks in one path, all the major ticks in another
    if(o.minor){b.lineWidth=2;b.beginPath();for(let v=o.min;v<=o.max+1e-6;v+=o.minor){const a=N(v);b.moveTo(x+Math.cos(a)*(r-8),y+Math.sin(a)*(r-8));b.lineTo(x+Math.cos(a)*(r-16),y+Math.sin(a)*(r-16));}b.stroke();}
    b.lineWidth=4;b.font='700 21px "B612",sans-serif';b.beginPath();
    for(let v=o.min;v<=o.max+1e-6;v+=o.major){const a=N(v);b.moveTo(x+Math.cos(a)*(r-8),y+Math.sin(a)*(r-8));b.lineTo(x+Math.cos(a)*(r-24),y+Math.sin(a)*(r-24));const t=o.fmt(v);if(t!=='')b.fillText(t,x+Math.cos(a)*(r-42),y+Math.sin(a)*(r-42));}
    b.stroke();
    if(o.lbl){b.font='700 14px "B612",sans-serif';b.fillStyle='#b9c0bb';b.fillText(o.lbl,x,y-28);}}
  c.setTransform(1,0,0,1,0,0);c.globalAlpha=1;c.drawImage(cv._vbg,0,0);c.textAlign='center';c.textBaseline='middle';
  if(o.win!=null){c.fillStyle='#000';c.fillRect(x-40,y+20,80,28);c.strokeStyle='#666';c.lineWidth=2;c.strokeRect(x-40,y+20,80,28);
    c.fillStyle='#eef0ea';c.font='700 19px "B612 Mono",monospace';c.fillText(o.win,x,y+35);}
  const nd=(v,len,w,col)=>{const a=N(v);c.strokeStyle=col;c.lineWidth=w;c.lineCap='round';c.beginPath();c.moveTo(x-Math.cos(a)*14,y-Math.sin(a)*14);c.lineTo(x+Math.cos(a)*len,y+Math.sin(a)*len);c.stroke();c.lineCap='butt';};
  if(o.vmax!=null)nd(o.vmax,r-22,3,'#ff8a3a');if(o.v2!=null)nd(o.v2,r-44,7,'#eef0ea');nd(o.v,r-14,5,'#f6f6f2');
  c.fillStyle='#202224';c.beginPath();c.arc(x,y,9,0,7);c.fill();}
function drawHSI(){const c=hsi,P=player,cx=128,cy=128;if(!chg(hsiC,P?Math.round(P.hdg*2)+','+Math.round(sys.hsi.hdg)+','+Math.round(sys.hsi.crs)+','+Math.round(Math.atan2(-P.pos.x,P.pos.z)*R2D*2)+','+Math.round(Math.hypot(P.pos.x,P.pos.z)/500)+','+isMig():'-'))return;c.fillStyle='#0c0d0e';c.fillRect(0,0,256,256);if(!P)return;
  c.fillStyle='#050606';c.beginPath();c.arc(cx,cy,118,0,7);c.fill();
  c.save();c.translate(cx,cy);c.rotate(-P.hdg*D2R);c.strokeStyle=c.fillStyle='#eef0ea';c.textAlign='center';c.textBaseline='middle';
  for(let d=0;d<360;d+=5){const a=d*D2R,l=d%10?8:d%30?13:18;c.lineWidth=d%30?2:3;c.beginPath();c.moveTo(Math.sin(a)*112,-Math.cos(a)*112);c.lineTo(Math.sin(a)*(112-l),-Math.cos(a)*(112-l));c.stroke();}
  c.font='700 20px "B612",sans-serif';for(let d=0;d<360;d+=30){c.save();c.rotate(d*D2R);c.fillText(d===0?'N':d===90?'E':d===180?'S':d===270?'W':String(d/10),0,-80);c.restore();}
  c.save();c.rotate(sys.hsi.hdg*D2R);c.fillStyle='#ff9a3a';c.fillRect(-10,-121,7,11);c.fillRect(3,-121,7,11);c.restore();
  {c.save();c.rotate(sys.hsi.crs*D2R);c.strokeStyle=c.fillStyle='#eef0ea';c.lineWidth=4;c.beginPath();c.moveTo(0,-100);c.lineTo(0,-58);c.moveTo(0,58);c.lineTo(0,100);c.stroke();
    c.beginPath();c.moveTo(0,-110);c.lineTo(-8,-95);c.lineTo(8,-95);c.closePath();c.fill();
    const bg=Math.atan2(-P.pos.x,P.pos.z)*R2D,dev=clamp((((bg-sys.hsi.crs)%360+540)%360-180)/10,-1,1)*44;
    c.lineWidth=4;c.beginPath();c.moveTo(dev,-50);c.lineTo(dev,50);c.stroke();c.lineWidth=2;[-44,-22,22,44].forEach(x=>{c.beginPath();c.arc(x,0,3,0,7);c.stroke();});c.restore();}
  c.rotate(Math.atan2(-P.pos.x,P.pos.z));c.strokeStyle=c.fillStyle='#ffd23a';c.lineWidth=4;// bearing pointer: home field at the map centre
  c.beginPath();c.moveTo(0,-98);c.lineTo(0,-40);c.moveTo(0,40);c.lineTo(0,104);c.stroke();c.beginPath();c.moveTo(0,-108);c.lineTo(-10,-88);c.lineTo(10,-88);c.closePath();c.fill();c.restore();
  c.strokeStyle='#ff9a3a';c.lineWidth=3;c.beginPath();c.moveTo(cx,cy-18);c.lineTo(cx,cy+16);c.moveTo(cx-17,cy-2);c.lineTo(cx+17,cy-2);c.moveTo(cx-7,cy+14);c.lineTo(cx+7,cy+14);c.stroke();
  c.fillStyle='#eef0ea';c.beginPath();c.moveTo(cx,cy-114);c.lineTo(cx-7,cy-126);c.lineTo(cx+7,cy-126);c.closePath();c.fill();
  c.font='700 18px "B612 Mono",monospace';c.textBaseline='middle';
  c.fillStyle='#000';c.fillRect(4,4,66,26);c.fillRect(186,4,66,26);c.fillStyle='#eef0ea';
  const mig=isMig();c.textAlign='left';c.fillText(String(Math.round(Math.hypot(P.pos.x,P.pos.z)/(mig?1000:NM))).padStart(3,'0'),12,18);
  c.textAlign='right';c.fillText(String(Math.round(sys.hsi.crs)%360).padStart(3,'0'),244,18);
  c.font='700 11px "B612",sans-serif';c.fillStyle='#9aa3a0';c.textAlign='left';c.fillText(mig?'D KM':'MILES',8,40);c.textAlign='right';c.fillText(mig?'COURSE':'COURSE',248,40);}
const SCP_TOP=['DIS\nLTS','AAM','A-G','GUN','SEL\nJETT'],SCP_BOT=['ON','STEP','SHIFT','LOAD','CLEAR'];
const scpRows=()=>player?[...player.missileTypes(),'GUN'].slice(0,3):[];
function drawSCP(){const c=scp,P=player;if(!chg(scpC,P?[game.wsel,game.arm,P.gun.ammo,P.chaff,P.flares,...scpRows().map(t=>t==='GUN'?0:P.count(t))].join():'-'))return;c.fillStyle='#1b1e20';c.fillRect(0,0,320,256);
  const btn=(x,y,w,h,t)=>{c.fillStyle='#2e3235';c.fillRect(x+3,y+3,w-6,h-6);c.strokeStyle='#08090a';c.lineWidth=2;c.strokeRect(x+3,y+3,w-6,h-6);
    c.fillStyle='#e9ece6';c.font='700 12px "B612",sans-serif';c.textAlign='center';c.textBaseline='middle';const ls=t.split('\n');ls.forEach((s,i)=>c.fillText(s,x+w/2,y+h/2+(i-(ls.length-1)/2)*13));};
  SCP_TOP.forEach((t,i)=>btn(i*64,0,64,42,t));SCP_BOT.forEach((t,i)=>btn(i*64,214,64,42,t));
  for(let i=0;i<5;i++){btn(0,44+i*34,38,34,'');btn(282,44+i*34,38,34,'');}
  c.fillStyle='#140603';c.fillRect(40,44,240,170);
  if(P){const w=game.wsel,mode=w==='GUN'?'GUN':MSL[w]&&MSL[w].seek==='IR'?'SRM':'MRM',L=[`${game.arm?'ARM':'SAF'}  ${mode}`];
    for(const t of scpRows())L.push(`${t===w?'>':' '}${(t==='GUN'?'GUN':SN[t]).padEnd(5)} ${t==='GUN'?P.gun.ammo:P.count(t)}`);
    while(L.length<4)L.push('');L.push(`CH${String(P.chaff).padStart(2,'0')}  FL${String(P.flares).padStart(2,'0')}`);
    c.save();c.font='700 25px "B612 Mono",monospace';c.textAlign='left';c.textBaseline='middle';c.fillStyle='#ff7a24';c.shadowColor='rgba(255,110,30,.8)';c.shadowBlur=7;
    L.forEach((s,i)=>c.fillText(s,48,61+i*34));c.restore();}
  c.fillStyle='rgba(20,6,3,.6)';for(let x=40;x<280;x+=3)c.fillRect(x,44,1,170);for(let y=44;y<214;y+=3)c.fillRect(40,y,240,1);}
function scpClick(x,y){const P=player;if(!P)return;sfx.click();
  if(y<44){const i=Math.floor(x/64);if(i===1){const t=P.missileTypes();if(!t.length){flash('NONE LOADED',900);return;}game.wsel=t[(t.indexOf(game.wsel)+1)%t.length];}
    else if(i===3)game.wsel='GUN';else if(i===4)jettison();return;}
  if(y>214){if(Math.floor(x/64)===1)cycleW(0);return;}
  const r=Math.floor((y-44)/34);if(r===0)setArm(game.armPos===0?1:0);else if(r>=1&&r<=3){const t=scpRows()[r-1];if(t)game.wsel=t;}}
