function vCaut(P){const v=sys.v||{},hp=P.hp,run=P.totalFuel>0,agl=P.pos.y-groundAt(P.pos.x,P.pos.z);
  return[[0,P.fuel<450,v.skid===0],[hp<30,P.fuel<300,!!v.hook],[0,0,0],[0,P.pos.y>15000,0],[hp<25||!run,hp<45,0],[hp<60,hp<50,0],[0,!!v.ralt&&agl<v.ralt,hp<35||!run],[0,v.cat===1&&P.tankFuel>0,0]];}
function vff(P){const ac=P.ac;return P.totalFuel>0?(lerp(ac.ff[0],ac.ff[1],P.n)+P.ab*(ac.ff[2]-ac.ff[1]))*Math.pow(rho(P.pos.y)/1.225,.7)*3600*2.2046:0;}
