   g.strokeStyle='#ffd23a';g.lineWidth=3;g.beginPath();g.moveTo(4,128);g.lineTo(62,128);g.stroke();g.fillStyle='#ffd23a';g.beginPath();g.moveTo(62,120);g.lineTo(54,128);g.lineTo(62,136);g.fill();
