// ACCEL wing-sweep indicator: needle on the actual sweep, a bug on the handle setting
function drawSweepInd(c,P){const x=96,y=96,r=86;c.fillStyle='#0a0b0b';c.fillRect(0,0,192,192);c.strokeStyle='#33383b';c.lineWidth=6;c.beginPath();c.arc(x,y,r+3,0,7);c.stroke();
  const A=v=>Math.PI*.8+(v-10)/70*Math.PI*1.4;c.strokeStyle=c.fillStyle='#eef0ea';c.lineWidth=3;c.font='700 20px "B612",sans-serif';c.textAlign='center';c.textBaseline='middle';
  for(let v=10;v<=80;v+=5){const a=A(v),b=v%10===0?14:8;c.beginPath();c.moveTo(x+Math.cos(a)*r,y+Math.sin(a)*r);c.lineTo(x+Math.cos(a)*(r-b),y+Math.sin(a)*(r-b));c.stroke();}
  [16,45,72].forEach(v=>{const a=A(v);c.fillStyle='#ffd040';c.fillText(String(v),x+Math.cos(a)*(r-32),y+Math.sin(a)*(r-32));});c.fillStyle='#eef0ea';c.font='700 13px "B612",sans-serif';c.fillText('SWEEP.',x,y+40);c.fillText('WING',x,y+56);
  if(!P||!P.ac.swing)return;const b=A(P.sweepCmd);c.fillStyle='#ff8a30';c.beginPath();c.moveTo(x+Math.cos(b)*(r+2),y+Math.sin(b)*(r+2));c.lineTo(x+Math.cos(b-.08)*(r-14),y+Math.sin(b-.08)*(r-14));c.lineTo(x+Math.cos(b+.08)*(r-14),y+Math.sin(b+.08)*(r-14));c.fill();
  const a=A(P.sweep);c.strokeStyle='#f4f4ee';c.lineWidth=5;c.beginPath();c.moveTo(x-Math.cos(a)*14,y-Math.sin(a)*14);c.lineTo(x+Math.cos(a)*(r-10),y+Math.sin(a)*(r-10));c.stroke();c.fillStyle='#333';c.beginPath();c.arc(x,y,8,0,7);c.fill();}
function sweepStep(d){if(f14SweepStep(d))return;const P=player;if(!P||!P.alive||!P.ac.swing)return;const A=[16,45,72];let i=A.indexOf(P.sweepCmd);if(i<0)i=1;i=clamp(i+d,0,2);if(A[i]===P.sweepCmd)return;P.sweepCmd=A[i];flash('WING '+A[i]+'°',900);sfx.click();}
const ip52C=mk(160,108),lifeC=mk(128,112),presC=mk(128,112),rampC=mk(128,112),voltC=mk(192,192),manoC=mk(192,192);
