      dz=v=>{const a=Math.abs(v);return a<DZ?0:Math.sign(v)*(a-DZ)/(1-DZ);},cv=v=>{v=dz(v);return(1-ex)*v+ex*v*v*v;},a=gp.axes,b=gp.buttons.map(x=>x.pressed),edge=i=>b[i]&&!gpPrev[i];
