sfx.amb=function(rain,wind,rumble){if(!this.ctx)return;const x=this.ctx;
  if(!this._an){const b=x.createBuffer(1,x.sampleRate*2,x.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;
    const mk=(type,f,q)=>{const s=x.createBufferSource();s.buffer=b;s.loop=true;s.start(Math.random());const fl=x.createBiquadFilter();fl.type=type;fl.frequency.value=f;fl.Q.value=q||.7;const g=x.createGain();g.gain.value=0;s.connect(fl).connect(g).connect(this.m);return{f:fl,g};};
    this._an={rain:mk('highpass',2400,.5),wind:mk('bandpass',500,.5),rum:mk('lowpass',160,.7)};}
  const t=x.currentTime,a=this._an;a.rain.g.gain.setTargetAtTime(rain*.09,t,.4);a.wind.g.gain.setTargetAtTime(wind*.12,t,.3);a.wind.f.frequency.setTargetAtTime(300+wind*900,t,.3);a.rum.g.gain.setTargetAtTime(rumble*.22,t,.15);};
sfx.thunder=function(){if(!this.ctx)return;const x=this.ctx,t=x.currentTime,b=x.createBuffer(1,x.sampleRate*4,x.sampleRate),d=b.getChannelData(0);let l=0;
  for(let i=0;i<d.length;i++){l+=(Math.random()*2-1-l)*.08;d[i]=l*Math.exp(-i/x.sampleRate*.9)*(1+.6*Math.sin(i/x.sampleRate*9));}
  const s=x.createBufferSource();s.buffer=b;const f=x.createBiquadFilter();f.type='lowpass';f.frequency.value=260;const g=x.createGain();g.gain.value=.9;s.connect(f).connect(g).connect(this.m);s.start(t);};

/* ============ damage model: component health, fire, fuel leaks, hydraulics, wing and tail loss ============ */
// A warhead that detonates close enough still kills outright; further out, or a gun hit, it chews up components. hp stays the airframe total.
const DMG_NAMES={eng:'ENGINE',wl:'L WING',wr:'R WING',tail:'TAIL',hyd:'HYDRAULICS',rdr:'RADAR',gear:'LANDING GEAR'};
const _dr=new V3();
Object.assign(Jet.prototype,{
  // direction-weighted choice of what a hit damaged; rel = hit point relative to the jet, in body axes (x right, y up, z aft)
  hitParts(rel){const wts={eng:.8,wl:.7,wr:.7,tail:.7,hyd:.9,rdr:.5,gear:.5,fuel:.8};
    if(rel){const l=rel.length()||1,x=rel.x/l,y=rel.y/l,z=rel.z/l;
      if(z<-.35){wts.rdr+=3*-z;wts.hyd+=1;}if(z>.35){wts.eng+=3.2*z;wts.tail+=2.6*z;wts.hyd+=1.2*z;}
      if(x<-.3){wts.wl+=3.2*-x;wts.gear+=.8;}if(x>.3){wts.wr+=3.2*x;wts.gear+=.8;}
      if(y<-.3){wts.gear+=2*-y;wts.fuel+=1.4*-y;}if(y>.3){wts.hyd+=1;wts.tail+=1*y;}}
    return wts;},
  pickPart(w){let t=0;for(const k in w)t+=w[k];let r=Math.random()*t;for(const k in w){r-=w[k];if(r<=0)return k;}return'hyd';},
  damage(d,src,hitPos){if(!this.alive)return;if(src)this.lastHitBy=src;
    const big=d>=40,frac=Math.min(1.1,d/200),dm=this.dm;
    if(big&&frac>=.82){this.hp=0;this.kill('SHOT DOWN',src);return;}
    this.hitT=1;if(this===player)this.shake=Math.max(this.shake,big?1.2:.45);
    let rel=null;{const hp=hitPos||this.hitFrom||(src&&src.pos);if(hp){rel=_dr.copy(hp).sub(this.pos).applyQuaternion(_dq2.copy(this.q).invert());}}
    const w=this.hitParts(rel);
    if(big){this.hp-=d*.4;const n=2+((Math.random()*2.2)|0);let budget=d*1.15;
      for(let i=0;i<n;i++){const p=this.pickPart(w),a=budget*(i===n-1?1:rnd(.3,.6));budget-=a;this.hurt(p,a);}}
    else{this.hp-=d;const p=this.pickPart(w);this.hurt(p,d*1.1);}
    if(this.hp<=0){this.kill('SHOT DOWN',src);return;}
    if(this===player&&big&&this.alive)flash('HIT',900);},
  hurt(p,a){const dm=this.dm;
    if(p==='fuel'){this.leak=Math.min(1.6,this.leak+a/70);if(a>25&&Math.random()<.18)this.ignite(.3);this.note('FUEL LEAK');return;}
    const before=dm[p];dm[p]=Math.max(0,dm[p]-a);
    if(p==='eng'){if(a>14&&Math.random()<Math.min(.85,a/45))this.ignite(.25+a/200);if(dm.eng<=0&&before>0){this.note('ENGINE FLAMEOUT');if(Math.random()<.6)this.ignite(.5);}}
    else if(p==='hyd'&&before>=30&&dm.hyd<30)this.note('HYD FAIL');
    else if(p==='wl'||p==='wr'){if(dm[p]<=0&&before>0)this.note(p==='wl'?'LEFT WING LOST':'RIGHT WING LOST');else if(a>10)this.note((p==='wl'?'L':'R')+' WING DAMAGE');if(a>25&&Math.random()<.2)this.leak=Math.min(1.6,this.leak+.25);}
    else if(p==='tail'){if(dm.tail<40&&before>=40)this.note('TAIL DAMAGE');}
    else if(p==='rdr'){if(dm.rdr<50&&before>=50)this.note('RADAR DEGRADED');if(dm.rdr<=0&&before>0)this.note('RADAR FAIL');}
    else if(p==='gear'&&dm.gear<30&&before>=30)this.note('GEAR DAMAGED');},
  note(t){if(this===player){flash(t,1600);if(typeof wingCallDmg==='function'&&0)0;}else if(this.ai&&this.ai.friend&&typeof wingHit==='function')wingHit(this,t);},
  ignite(k){if(this.fire<=0){this.fireT=0;this.extUsed=false;if(this===player)flash('FIRE',2000);else if(this.ai&&this.ai.friend&&typeof wingHit==='function')wingHit(this,'FIRE');}
    this.fire=Math.min(1,Math.max(this.fire,k||.3));},
  extinguish(){if(this.fire<=0){return false;}if(this.extUsed){flash('EXTINGUISHER EMPTY',1400);return true;}this.extUsed=true;
    const ok=Math.random()<(this.thr<.35?.9:.55);
    if(ok){this.fire=0;this.dm.eng=Math.min(this.dm.eng,Math.max(0,this.dm.eng-10));flash('FIRE OUT',1800);}else flash('EXTINGUISHER DISCHARGED · FIRE PERSISTS',2200);return true;},
  dmgTick(dt){const dm=this.dm;
    if(this.hitT>0)this.hitT=Math.max(0,this.hitT-dt*2);
    if(this.fire>0){this.fireT+=dt;this.fire=Math.min(1,this.fire+dt*.01);
      this.hp-=(.5+2.6*this.fire)*dt;dm.eng=Math.max(0,dm.eng-this.fire*1.4*dt);
      if(this.fireT>6&&this.fire>.5)dm.hyd=Math.max(0,dm.hyd-this.fire*.9*dt);
      if(this.ai&&!this.extUsed&&this.fireT>3.5){this.extUsed=true;if(Math.random()<.45){this.fire=0;if(this.ai.friend&&typeof wingHit==='function')wingHit(this,'FIRE OUT');}}
      if(this.fire>0&&Math.random()<dt*70*this.fire){const f=this.fwd(_f);const p=this.pos.clone().addScaledVector(f,6);
        glow.emit(p,this.vel.clone().multiplyScalar(.9),.18,1.8*(.6+this.fire),.4,1,.55,.12,.95);
        if(Math.random()<.5)smoke.emit(p,this.vel.clone().multiplyScalar(.96),4,1.6,9,.07,.07,.07,.8,.3);}
      if(this.hp<=0){this.kill('FIRE',this.lastHitBy);return;}}
    if(this.leak>0){const rate=this.leak*(this.ac.ff[1]*.35+4)*dt;this.fuel=Math.max(0,this.fuel-rate);
      if(Math.random()<dt*40*this.leak){const f=this.fwd(_f);smoke.emit(this.pos.clone().addScaledVector(f,3),this.vel.clone().multiplyScalar(.95),2.5,.5,3,.9,.9,.85,.28,.5);}
      if(this.fire<=0&&dm.eng<70&&Math.random()<dt*.03*this.leak)this.ignite(.3);
      if(this.fuel<=0)this.leak=0;}
    // damaged engine smokes, a dead one trails dark smoke
    if(dm.eng<55&&Math.random()<dt*(dm.eng<=0?30:14)){smoke.emit(this.pos.clone().addScaledVector(this.fwd(_f),5),this.vel.clone().multiplyScalar(.97),4,1.2,8,.1,.1,.1,.5,.3);}
    if((dm.wl<45||dm.wr<45)&&Math.random()<dt*10){const sx=dm.wl<dm.wr?-3:3;smoke.emit(this.pos.clone().addScaledVector(this.right(_r),sx),this.vel.clone().multiplyScalar(.97),3,.8,5,.18,.18,.18,.4,.3);}
    if(this.alive&&this===player)this.dmgPlayerFx(dt);
    // radar degradation (AI uses rdrK; the player's radar picks it up through radar.R0 in dmgPlayerFx)
    this.rdrK=dm.rdr<=0?.03:.25+.75*dm.rdr/100;},
  dmgPlayerFx(dt){
    radar.R0=this.ac.radar.R0*this.rdrK;
    if(this.dm.rdr<=0&&radar.power!=='OFF'&&!this._rdrOff){this._rdrOff=true;}
  },
  eject(){if(this!==player||!this.alive)return;this.alive=false;this.ejected=true;this.hp=0;this.trigger=false;onPlayerDead('EJECTED',this.lastHitBy);},
  healAll(){const dm=this.dm;for(const k in dm)dm[k]=100;this.fire=0;this.leak=0;this.hp=100;}
});
