  rainOn=true;const W=Math.round(innerWidth*.6),H=Math.round(innerHeight*.6),cx=W/2,cy=H*.46,ck=view==='cockpit';
  if(rainC.width!==W)rainC.width=W;if(rainC.height!==H)rainC.height=H;   // assigning the size reallocates the bitmap: only on a real change
  const sp=live&&!P.onGnd?clamp(P.cas/260,0,1):live?clamp(P.vel.length()/120,0,.5):0;
  rainX.clearRect(0,0,W,H);rainX.lineCap='round';
  const n=Math.floor(RP.length*Math.min(1,k)*(ck?1:.7));
  for(let i=0;i<n;i++){const p=RP[i];let rx=p.x*W-cx,ry=p.y*H-cy;const rl=Math.hypot(rx,ry)||1;rx/=rl;ry/=rl;
    let dx=rx*sp,dy=ry*sp+(1-sp)*1.2;const dl=Math.hypot(dx,dy)||1;dx/=dl;dy/=dl;
    const sn=ENV.snow,v=(250+p.s*420)*(.35+sp*1.5)*(sn?.32:1),len=sn?(2+p.s*3)*(1+sp*3):(10+p.s*28)*(.5+sp*2.2);
    p.x+=dx*v*dt/W;p.y+=dy*v*dt/H;
    if(p.x<-.05||p.x>1.05||p.y<-.05||p.y>1.05){if(sp>.45){const a=Math.random()*6.2832,r=Math.random()*.12;p.x=.5+Math.cos(a)*r;p.y=.46+Math.sin(a)*r;}else{p.x=Math.random();p.y=-.03;}}
    rainX.strokeStyle=ENV.snow?'rgba(245,248,252,'+(.35+.4*p.s)*Math.min(1,k*1.3)+')':'rgba(215,226,238,'+(.1+.17*p.s)*Math.min(1,k*1.3)+')';rainX.lineWidth=ENV.snow?1.6+p.s*2.2:.7+p.s*.8;
    rainX.beginPath();rainX.moveTo(p.x*W,p.y*H);rainX.lineTo(p.x*W-dx*len,p.y*H-dy*len);rainX.stroke();}
