function buildAG(kind){const a=AGW[kind],g=new THREE.Group(),w=SKIN(a.col,30),dk=SKIN(0x2a2d30,20),bd=SKIN(a.band||0x3a3e42,30),R=a.R,L=a.L;
  const cyl=(r0,r1,len,m,z,seg=16)=>{const c=new THREE.Mesh(new THREE.CylinderGeometry(r0,r1,len,seg),m);c.rotation.x=Math.PI/2;c.position.z=z;g.add(c);return c;};
  if(a.k==='bomb'){cyl(R,R,L*.5,w,0);cyl(R*.18,R,L*.24,w,-L*.37);cyl(R,R*.45,L*.26,w,L*.38);cyl(R*.2,R*.2,.08,dk,-L*.5);
    cyl(R*1.01,R*1.01,.05,bd,-L*.22);for(let i=0;i<4;i++){const f=new THREE.Mesh(new THREE.BoxGeometry(.012,R*1.5,L*.2),w);const an=i*Math.PI/2+Math.PI/4;
      f.position.set(Math.cos(an)*R*.75,Math.sin(an)*R*.75,L*.42);f.rotation.z=an-Math.PI/2;g.add(f);}
    if(kind==='FAB-250'){const lug=new THREE.Mesh(new THREE.TorusGeometry(R*.6,.02,6,16),dk);lug.position.z=-L*.12;g.add(lug);}}
  else{cyl(R,R,L*.82,w,.05);cyl(R*.6,R,L*.12,w,-L*.45);cyl(R*.85,R,L*.08,w,L*.45);
    const face=new THREE.Mesh(new THREE.CircleGeometry(R*.62,18),dk);face.position.z=-L*.51;face.rotation.y=Math.PI;g.add(face);
    const n=a.cap>4?7:4;for(let i=0;i<n;i++){const t=new THREE.Mesh(new THREE.CircleGeometry(R*(n>4?.14:.24),10),SKIN(0x0a0a0a,5));const an=i/n*Math.PI*2,rr=i?R*.4:0;
      t.position.set(Math.cos(an)*rr,Math.sin(an)*rr,-L*.515);t.rotation.y=Math.PI;g.add(t);}
    cyl(R*1.01,R*1.01,.04,dk,-L*.2);cyl(R*1.01,R*1.01,.04,dk,L*.25);}
  return g;}
