const GV=new V3(),GUP=new V3(0,1,0);
function gMesh(kind){const g=new THREE.Group(),ol=SKIN(0x56603e,18),od=SKIN(0x3e4630,16),dk=SKIN(0x23262a,12),cr=SKIN(0x9a9480,16),rd=SKIN(0x7a3a2a,18);
  const box=(w,h,l,m,x,y,z,ry=0)=>{const b=new THREE.Mesh(new THREE.BoxGeometry(w,h,l),m);b.position.set(x,y,z);b.rotation.y=ry;g.add(b);return b;};
  const tracks=(w,l)=>{box(.55,.9,l,dk,-w/2+.28,.45,0);box(.55,.9,l,dk,w/2-.28,.45,0);};
  if(kind==='SURN'){tracks(3.2,7.2);box(3,1.2,7,ol,0,1.4,0);box(2.6,.9,2.4,od,0,2.4,1.6);
    const ant=new THREE.Group();ant.position.set(0,3.1,-.8);g.add(ant);g.userData.ant=ant;
    const d1=new THREE.Mesh(new THREE.CylinderGeometry(1.6,1.6,.2,20),cr);d1.rotation.x=Math.PI/2-.25;d1.position.y=1.2;ant.add(d1);
    const d2=new THREE.Mesh(new THREE.CylinderGeometry(.9,.9,.2,16),cr);d2.rotation.x=Math.PI/2-.1;d2.position.set(0,1.1,.7);ant.add(d2);
    const mst=new THREE.Mesh(new THREE.CylinderGeometry(.25,.35,1,8),od);mst.position.y=.4;ant.add(mst);}
  else if(kind==='TEL'){tracks(3.2,6.8);box(3,1.1,6.6,ol,0,1.35,0);
    const tt=new THREE.Group();tt.position.set(0,2.05,.4);g.add(tt);g.userData.tt=tt;const rail=new THREE.Group();rail.position.y=.5;tt.add(rail);g.userData.rail=rail;
    box(.0,.0,.0,ol,0,0,0);const base=new THREE.Mesh(new THREE.CylinderGeometry(1.1,1.2,.5,12),od);tt.add(base);
    g.userData.rounds=[-1,0,1].map(i=>{const m=makeStore('3M9');m.position.set(i*.75,.45,0);rail.add(m);return m;});}
  else if(kind==='ZSU'){tracks(3,6.4);box(2.9,1.1,6.2,ol,0,1.3,0);
    const tur=new THREE.Group();tur.position.set(0,1.85,-.3);g.add(tur);g.userData.tur=tur;
    const tb=new THREE.Mesh(new THREE.BoxGeometry(2.7,1.1,3),od);tb.position.y=.55;tur.add(tb);
    const gun=new THREE.Group();gun.position.set(0,.9,-1.2);tur.add(gun);g.userData.gun=gun;
    for(const [x,y] of [[-.55,.18],[.55,.18],[-.55,-.12],[.55,-.12]]){const b=new THREE.Mesh(new THREE.CylinderGeometry(.06,.07,2.4,8),dk);b.rotation.x=Math.PI/2;b.position.set(x,y,-1.2);gun.add(b);}
    const dish=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,.12,14),cr);dish.rotation.x=Math.PI/2-.3;dish.position.set(0,1.6,1.1);tur.add(dish);g.userData.dish=dish;}
  else if(kind==='TRUCK'){box(2.4,1.2,7,dk,0,.7,0);box(2.4,1.6,2.1,ol,0,1.7,-2.4);box(2.4,1.9,4.4,SKIN(0x6b6a4e,12),0,2.05,.9);
    for(const z of [-2.4,.6,2.2])for(const x of [-1.1,1.1]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,.4,10),dk);w.rotation.z=Math.PI/2;w.position.set(x,.55,z);g.add(w);}}
  else if(kind==='TANK'){tracks(3.5,6.9);box(3.3,1.0,6.6,ol,0,1.15,0);
    const tur=new THREE.Mesh(new THREE.CylinderGeometry(1.35,1.6,.9,12),od);tur.position.set(0,2.05,.3);g.add(tur);
    const gun=new THREE.Mesh(new THREE.CylinderGeometry(.09,.11,5.2,8),dk);gun.rotation.x=Math.PI/2;gun.position.set(0,2.15,-2.6);g.add(gun);}
  else if(kind==='BLDG'){box(22,6,12,cr,0,3,0);box(22.6,.6,12.6,rd,0,6.2,0);box(4,4,.2,dk,-5,2,-6.05);box(4,4,.2,dk,5,2,-6.05);}
  g.traverse(o=>{if(o.isMesh){o.castShadow=false;o.receiveShadow=false;}});return g;}

class GUnit{
  constructor(kind,side,x,z,hdg){const T=GTY[kind];this.gnd=true;this.kind=kind;this.T=T;this.side=side;this.hp=T.hp;this.alive=true;this.type=T.n;this.callsign=T.n;
    const y=groundAt(x,z);this.pos=new V3(x,y,z);this.vel=new V3();this.hdg=hdg||0;this.aim=new V3(Math.sin(this.hdg*D2R),0,-Math.cos(this.hdg*D2R));
    this.ac={rcs:T.rcs||10,irs:.4,radar:T.R0?{R0:T.R0}:null,rwr:T.rwr||'U',spo:T.spo!=null?T.spo:5,name:T.n};
    this.ai={radarLock:false,t:null,friend:false,hojLock:false,target:null};
    this.mesh=gMesh(kind);this.mesh.position.copy(this.pos);this.mesh.rotation.y=-this.hdg*D2R;scene.add(this.mesh);this.burnT=0;GINST.adopt(this);}
  fwd(v){return v.copy(this.aim);}
  up(v){return v.copy(GUP);}
  damage(d,src){if(!this.alive)return;this.hp-=d;if(this.hp<=0)this.kill(src);}
  kill(src){if(!this.alive)return;this.alive=false;this.ai.radarLock=false;this.burnT=90;explode(this.pos.clone().setY(this.pos.y+2),true);
    this.mesh.traverse(o=>{if(o.isMesh&&o.material){o.material=o.material.clone();o.material.color.multiplyScalar(.22);}});
    if(this.mesh.userData.ant)this.mesh.userData.ant.rotation.z=.6;
    if(src===player){GND.kills++;flash((this.T.tgt?'TARGET DESTROYED · ':this.kind==='ZSU'?'SHILKA DOWN · ':'SAM HIT · ')+this.T.n.toUpperCase(),2200);if(SET.calls==='ON')radio(this.T.n+' destroyed.');}}
  tick(dt){if(this.alive)return;if(this.burnT>0){this.burnT-=dt;if(Math.random()<dt*6)smoke.emit(this.pos.clone().setY(this.pos.y+3),GV.set(rnd(-1,1),rnd(5,9),rnd(-1,1)),rnd(8,14),5,28,.12,.11,.1,.55,.05);
      if(this.burnT>60&&Math.random()<dt*10)glow.emit(this.pos.clone().setY(this.pos.y+1.5),null,.4,3,6,1,.55,.15,.9);}}
}

const GND={units:[],bombs:[],rkts:[],sites:[],zsus:[],kills:0,targets:0,
  clear(){for(const u of this.units)scene.remove(u.mesh);for(const b of this.bombs)scene.remove(b.mesh);for(const r of this.rkts)scene.remove(r.mesh);
    this.units.length=this.bombs.length=this.rkts.length=this.sites.length=this.zsus.length=0;this.kills=0;this.targets=0;this.t=0;},
  add(kind,side,x,z,hdg){const u=new GUnit(kind,side,x,z,hdg);this.units.push(u);if(u.T.tgt)this.targets++;return u;},
  // the target area: a depot, a truck park and a tank platoon, a Kub battery 5 km beyond it and two Shilkas inside it
  setup(P){this.clear();const hd=P.hdg*D2R,fx=Math.sin(hd),fz=-Math.cos(hd),rx=-fz,rz=fx;
    let best=null;for(let d=26000;d<=60000;d+=2000)for(let s=-12000;s<=12000;s+=3000){const x=P.pos.x+fx*d+rx*s,z=P.pos.z+fz*d+rz*s,h=groundAt(x,z);
      if(h<15||h>900)continue;let sl=0;for(const[a,b]of[[400,0],[-400,0],[0,400],[0,-400]])sl=Math.max(sl,Math.abs(groundAt(x+a,z+b)-h));if(sl>40)continue;
      const sc=Math.abs(s)/12000+sl/40+Math.abs(d-40000)/40000;if(!best||sc<best.sc)best={x,z,sc};}
    if(!best)best={x:P.pos.x+fx*40000,z:P.pos.z+fz*40000};
    const C=best,at=(f,r)=>[C.x+fx*f+rx*r,C.z+fz*f+rz*r],H=P.hdg;this.center=new V3(C.x,groundAt(C.x,C.z),C.z);
    for(const[f,r]of[[0,-40],[0,40],[60,0]]){const[x,z]=at(f,r);this.add('BLDG',1,x,z,H+90);}
    for(let i=0;i<6;i++){const[x,z]=at(-120-(i%3)*14,-60+Math.floor(i/3)*120+((i%3)-1)*4);this.add('TRUCK',1,x,z,H);}
    for(let i=0;i<4;i++){const[x,z]=at(260+i*45,(i%2?1:-1)*18);this.add('TANK',1,x,z,H+180);}
    for(const r of[-700,700]){const[x,z]=at(-300,r);this.zsus.push(this.add('ZSU',1,x,z,H+180));}
    {const[x,z]=at(5000,1500),s=this.add('SURN',1,x,z,H+180),tels=[];
      for(const[f,r]of[[220,0],[-220,0],[0,220],[0,-220]]){const[tx,tz]=at(5000+f,1500+r);const t=this.add('TEL',1,tx,tz,H+180);t.n=3;tels.push(t);}
      this.sites.push({surn:s,tels,st:'search',det:0,trk:null,salvo:0,nextL:0,sweep:0,notchT:0,msl:[],lostT:0});}},
  tick(dt){if(!this.units.length&&!this.bombs.length&&!this.rkts.length)return;this.t=(this.t||0)+dt;const now=this.t;// simulation time, so pauses and slow frames don't skew the reaction timers
    for(const u of this.units)u.tick(dt);
    for(const S of this.sites)this.sam(S,dt,now);
    for(const z of this.zsus)this.zsu(z,dt,now);
    {const n=Math.max(1,Math.ceil(dt/.02-1e-6)),h=dt/n;for(let i=0;i<n;i++){this.flyBombs(h);this.flyRkts(h);}}},
  check(){if(game.over||!this.targets)return;const left=this.units.filter(u=>u.T.tgt&&u.alive).length;
    if(left===0){game.over=true;game.result='TARGETS DESTROYED';game.endT=6;setTimeout(()=>flash('ALL TARGETS DESTROYED · RTB',4000),1500);}},
  // what an emitter can see: line of sight, clutter floor, and its own range against this target's RCS
  canSee(u,P,R0,floor){if(!P.alive)return false;const d=u.pos.distanceTo(P.pos);if(d>R0*Math.pow(Math.max(.5,P.ac.rcs)/6,.25))return false;
    const agl=P.pos.y-groundAt(P.pos.x,P.pos.z);if(agl<floor)return false;
    return terrLOS(_gwA.copy(u.pos).setY(u.pos.y+4),P.pos);},
  /* ---- 2K12 Kub battery: search -> acquire (reaction time) -> CW illumination -> two-round salvo ---- */
  sam(S,dt,now){const R=S.surn,P=player;if(!R.alive){R.ai.radarLock=false;return;}
    S.sweep=(S.sweep+dt*Math.PI*2/4)%(Math.PI*2);// 1S11 antenna turns at 15 rpm
    const ant=R.mesh.userData.ant;
    const tgt=P&&P.alive&&(P.side!==R.side||IFF.sam(P,R))?P:null;
    const rel=tgt?_gwB.copy(tgt.pos).sub(R.pos):null,d=rel?rel.length():1e9,brg=rel?Math.atan2(rel.x,-rel.z):0;
    const vis=tgt&&this.canSee(R,tgt,GTY.SURN.R0*1.5,20);
    // radial (Doppler) speed: the CW tracker and the missile's seeker both need a closing or opening rate
    const vr=tgt?Math.abs(tgt.vel.dot(rel.clone().normalize())):0,notch=vr<35;
    const jm=tgt?jamOfMsl(tgt,MSL['3M9'],R.pos):null,jam=!!(jm&&jm.noise&&jm.far);
    if(S.st==='search'){R.aim.set(Math.sin(S.sweep),.05,-Math.cos(S.sweep)).normalize();if(ant)ant.rotation.y=-S.sweep+R.hdg*D2R;
      // the beam paints the target once a turn
      if(vis&&!jam){let db=Math.abs(((brg-S.sweep)%(Math.PI*2)+Math.PI*3)%(Math.PI*2)-Math.PI);if(db<.08){S.det=Math.max(S.det,now);if(!S.acq)S.acq=now;S.lastPaint=now;}}
      if(S.acq&&now-(S.lastPaint||0)>9)S.acq=0;
      if(S.acq&&d<28000&&now-S.acq>22+Math.random()*.5){S.st='track';S.trk=tgt;S.lostT=0;if(SET.calls==='ON'&&P===tgt&&!isMig())radio('Spike! SA-6 tracking.');}}
    if(S.st==='track'){const T=S.trk;R.aim.copy(rel||R.aim).normalize();if(ant)ant.rotation.y=-brg+R.hdg*D2R;
      const ok=T&&T.alive&&vis&&d<30000&&!jam;
      if(ok&&notch){S.notchT+=dt;}else S.notchT=0;
      const lock=ok&&S.notchT<1.2;R.ai.radarLock=lock;R.ai.t=lock?T:null;
      if(!ok){S.lostT+=dt;if(S.lostT>4){S.st='search';S.acq=0;R.ai.radarLock=false;R.ai.t=null;return;}}else S.lostT=0;
      S.msl=S.msl.filter(m=>m.alive);
      const alt=T.pos.y-R.pos.y,spd=T.vel.length();
      if(lock&&!S.msl.length&&now>S.nextL&&d>4000&&d<25000&&alt>20&&alt<8000&&spd<620){S.salvo=2;S.nextL=now;}
      if(S.salvo>0&&lock&&now>=S.nextL){const L=S.tels.find(t=>t.alive&&t.n>0);if(!L){S.salvo=0;return;}
        this.launch(S,L,T);S.salvo--;S.nextL=now+(S.salvo>0?4.5:30);}}},
  launch(S,L,T){const R=S.surn,lp=L.pos.clone().setY(L.pos.y+3.2),to=T.pos.clone().addScaledVector(T.vel,8).sub(lp),hz=Math.hypot(to.x,to.z),
      el=Math.max(Math.atan2(to.y,hz),14*D2R),dir=new V3(to.x/hz*Math.cos(el),Math.sin(el),to.z/hz*Math.cos(el)).normalize();
    L.n--;const rd=L.mesh.userData.rounds;if(rd&&rd[L.n])rd[L.n].visible=false;
    const tt=L.mesh.userData.tt;if(tt){tt.rotation.y=-Math.atan2(to.x,-to.z)+L.hdg*D2R;const rl=L.mesh.userData.rail;if(rl)rl.rotation.x=el;}
    // the missile flies off the launcher rail but homes on the SURN's illumination: the radar vehicle is its 'shooter'
    const sh={gnd:true,side:R.side,get alive(){return R.alive;},ai:R.ai,pos:L.pos,vel:new V3(),ac:R.ac,type:'SA-6',callsign:'SA-6',fwd:v=>v.copy(dir),up:v=>v.set(-dir.x*dir.y,1-dir.y*dir.y,-dir.z*dir.y).normalize()};
    const m=new Missile('3M9',sh,T,lp);m.vel.copy(dir).multiplyScalar(25);S.msl.push(m);
    for(let i=0;i<14;i++)smoke.emit(lp,GV.set(rnd(-6,6),rnd(0,4),rnd(-6,6)),rnd(4,8),4,18,.85,.84,.8,.6,.3);
    if(T===player&&SET.calls==='ON'&&!isMig())radio('SAM launch!');},
  /* ---- ZSU-23-4: RPK-2 radar or optical tracking, 1A7 computed lead, bursts from four barrels ---- */
  zsu(Z,dt,now){const P=player;if(!Z.alive){Z.ai.radarLock=false;return;}
    Z.ammo=Z.ammo==null?2000:Z.ammo;Z.sw=((Z.sw||0)+dt*Math.PI*2/1.8)%(Math.PI*2);
    const tgt=P&&P.alive&&P.side!==Z.side?P:null;if(!tgt){Z.ai.radarLock=false;return;}
    const rel=_gwB.copy(tgt.pos).sub(Z.pos),d=rel.length(),agl=tgt.pos.y-groundAt(tgt.pos.x,tgt.pos.z);
    const los=d<20000&&terrLOS(_gwA.copy(Z.pos).setY(Z.pos.y+3.5),tgt.pos);
    const jm=jamOfMsl(tgt,MSL['3M9'],Z.pos),jam=!!(jm&&jm.noise&&jm.far&&d>4000);
    const radar=los&&agl>60&&d<12000&&!jam,optic=los&&d<3500&&(typeof ENV==='undefined'||!ENV.night);
    const trk=radar||optic;Z.ai.radarLock=radar;Z.ai.t=radar?tgt:null;
    const tur=Z.mesh.userData.tur,gun=Z.mesh.userData.gun,dish=Z.mesh.userData.dish;
    if(!trk){Z.aim.set(Math.sin(Z.sw),.1,-Math.cos(Z.sw)).normalize();if(tur)tur.rotation.y=-Z.sw+Z.hdg*D2R;Z.trkT=0;return;}
    Z.trkT=(Z.trkT||0)+dt;
    // fire-control lead: time of flight from the drag law the rounds obey, gravity drop added back
    let t=d/950;for(let i=0;i<3;i++){const ap=_gwC.copy(tgt.pos).addScaledVector(tgt.vel,t);t=ap.distanceTo(Z.pos)/(980*(1-.03*t*rho(Z.pos.y)));}
    const ap=_gwC.copy(tgt.pos).addScaledVector(tgt.vel,t);ap.y+=.5*G*t*t;const dir=_gwD.copy(ap).sub(Z.pos).normalize();Z.aim.copy(dir);
    if(tur)tur.rotation.y=-Math.atan2(dir.x,-dir.z)+Z.hdg*D2R;if(gun)gun.rotation.x=Math.asin(clamp(dir.y,-1,1));
    // tracking error: radar settles in about 3 s; a fast crossing target inside 7-8 km out-runs the tracking drives; optical laying is coarser
    const om=tgt.vel.clone().sub(rel.clone().multiplyScalar(tgt.vel.dot(rel)/(d*d))).length()/Math.max(d,1);
    const err=(radar?.003:.006)+clamp(om*.35,0,.02)+.012*Math.exp(-Z.trkT/1.5);
    if(d<(Z.T.gr||2600)&&tgt.pos.y-Z.pos.y<2000&&Z.ammo>0){Z.burst=Z.burst||0;Z.cd=(Z.cd||0)-dt;
      if(Z.burst<=0&&Z.cd<=0){Z.burst=rnd(.35,.7);Z.cd=rnd(1.2,2.4);Z.bias=new V3(rnd(-1,1),rnd(-1,1),rnd(-1,1)).multiplyScalar(err);}
      if(Z.burst>0){Z.burst-=dt;Z.acc=(Z.acc||0)+dt*57;const mz=_gwA.copy(Z.pos).setY(Z.pos.y+3).addScaledVector(dir,3);
        while(Z.acc>=1&&Z.ammo>0){Z.acc--;Z.ammo--;const b=bulletNew(Z,Z.T.gd||11,1);b.p.copy(mz);
          b.v.copy(dir).add(Z.bias).add(_ugD.set(rnd(-1,1),rnd(-1,1),rnd(-1,1)).multiplyScalar(.0022)).normalize().multiplyScalar(980);}
        if(Math.random()<.5)glow.emit(mz,null,.06,3,2,1,.8,.4,1);}}},
  // a gun round from the player: segment against each live unit
  bullet(a,b,bl){for(const u of this.units){if(!u.alive)continue;const r=u.T.r;if(a.distanceToSquared(u.pos)>9e4&&b.distanceToSquared(u.pos)>9e4)continue;
      const c=_gwA.copy(u.pos).setY(u.pos.y+1.5);if(segPt(a,b,c)<r){u.damage(bl.dmg*(u.T.arm?.08:1),bl.o);glow.emit(b,null,.2,3,6,1,.8,.4,1);return true;}}return false;},
  // blast and fragments: soft targets inside the lethal radius, armour only close in
  blast(p,w,src){explode(p,true);for(let i=0;i<10;i++)smoke.emit(p,GV.set(rnd(-15,15),rnd(8,30),rnd(-15,15)),rnd(4,9),8,40,.24,.21,.18,.7,.4);
    for(const u of this.units){if(!u.alive)continue;const dd=Math.max(0,u.pos.distanceTo(p)-u.T.r*.5),R=u.T.arm?w.hard:w.soft;if(dd<R)u.damage((u.T.arm?220:160)*(1-dd/R)+20,src);}
    if(player&&player.alive){const dd=player.pos.distanceTo(p);if(dd<w.soft*2.2&&src===player){player.hitFrom=p.clone();player.damage(60*(1-dd/(w.soft*2.2)),null);flash('FRAG DAMAGE',1500);}}},
  /* ---- free-fall bombs ---- */
  drop(kind,P,pos){const w=AGW[kind],m=makeStore(kind);scene.add(m);const b={kind,w,p:pos.clone(),v:P.vel.clone().add(P.up(new V3()).multiplyScalar(-1.5)),t:0,mesh:m,src:P};
    this.bombs.push(b);game.stats.shots++;},
  flyBombs(dt){for(let i=this.bombs.length-1;i>=0;i--){const b=this.bombs[i];this.stepBomb(b.p,b.v,b.w.kd,dt);b.t+=dt;
      b.mesh.position.copy(b.p);const V=b.v.length();if(V>1)b.mesh.quaternion.setFromUnitVectors(_Z,_gwA.copy(b.v).divideScalar(V));
      if(b.p.y<=groundAt(b.p.x,b.p.z)){b.p.y=groundAt(b.p.x,b.p.z)+.5;if(b.t>1.2)this.blast(b.p,b.w,b.src);else smoke.emit(b.p,null,2,3,6,.4,.35,.3,.5);scene.remove(b.mesh);this.bombs.splice(i,1);}}},
  stepBomb(p,v,kd,dt){const V=v.length();v.addScaledVector(v,-kd*rho(p.y)/1.225*V*dt);v.y-=G*dt;p.addScaledVector(v,dt);},
  /* ---- rockets: boost along the launch line, then ballistic with drag; HEAT / HE on impact ---- */
  fire(kind,P,pos){const a=AGW[kind],r=RKT[a.rk],f=P.fwd(new V3()),d=f.clone().add(new V3(rnd(-1,1),rnd(-1,1),rnd(-1,1)).multiplyScalar(r.disp)).normalize();
    const m=new THREE.Mesh(new THREE.CylinderGeometry(.04,.04,1.4,6),SKIN(0xd8d6ca));m.rotation.x=Math.PI/2;const g=new THREE.Group();g.add(m);scene.add(g);
    this.rkts.push({r,p:pos.clone().addScaledVector(f,3),v:P.vel.clone(),d,t:0,mesh:g,src:P});},
  flyRkts(dt){for(let i=this.rkts.length-1;i>=0;i--){const k=this.rkts[i],r=k.r,prev=k.p.clone();this.stepRkt(k.p,k.v,k.d,k.t,r,dt);k.t+=dt;
      k.mesh.position.copy(k.p);const V=k.v.length();if(V>1)k.mesh.quaternion.setFromUnitVectors(_Z,_gwA.copy(k.v).divideScalar(V));
      if(k.t<r.burn){smoke.emit(k.p,null,rnd(1.2,2),1.2,5,.9,.9,.88,.45,.3);glow.emit(k.p,null,.04,1.6,1,1,.8,.4,1);}
      let hit=null;for(const u of this.units)if(u.alive&&segPt(prev,k.p,_gwA.copy(u.pos).setY(u.pos.y+1.5))<u.T.r){hit=u;break;}
      const gy=groundAt(k.p.x,k.p.z);if(hit||k.p.y<=gy||k.t>25){if(hit){hit.damage(hit.T.arm?(k.r.hard>2.4?60:110):80,k.src);}
        if(k.p.y<=gy)k.p.y=gy+.3;this.blast(k.p,{soft:r.soft,hard:r.hard},k.src);scene.remove(k.mesh);this.rkts.splice(i,1);}}},
  stepRkt(p,v,d,t,r,dt){if(t<r.burn)v.addScaledVector(d,r.dv/r.burn*dt);const V=v.length();v.addScaledVector(v,-r.kd*rho(p.y)/1.225*V*dt);v.y-=G*dt;p.addScaledVector(v,dt);},
  // CCIP: fly the selected store from where it would leave the jet now and return the impact point
  ccip(P,kind){const a=AGW[kind];if(!a)return null;const p=_gwE.copy(P.pos),v=_gwF.copy(P.vel);let t=0;const dt=a.k==='bomb'?.04:.02;
    if(a.k==='bomb'){v.addScaledVector(P.up(_gwG),-1.5);while(t<90){this.stepBomb(p,v,a.kd,dt);t+=dt;if(p.y<=groundAt(p.x,p.z))return{p:p.clone(),t};}}
    else{const r=RKT[a.rk],d=P.fwd(_gwG).clone();p.addScaledVector(d,3);while(t<25){this.stepRkt(p,v,d,t,r,dt);t+=dt;if(p.y<=groundAt(p.x,p.z))return{p:p.clone(),t,rng:p.distanceTo(P.pos),max:r.range};}}
    return null;},
  // emitters for the warning receivers, in the same shape as the airborne threats
  threats(P,out){for(const u of this.units){if(!u.alive||!u.T.emit||u.side===P.side)continue;const d=u.pos.distanceTo(P.pos);if(d>u.T.R0*1.6)continue;
      if(!terrLOS(_gwA.copy(u.pos).setY(u.pos.y+4),P.pos))continue;out.push({j:u,d,lk:u.ai.radarLock&&u.ai.t===P,gnd:1});}}};
const _gwA=new V3(),_gwB=new V3(),_gwC=new V3(),_gwD=new V3(),_gwE=new V3(),_gwF=new V3(),_gwG=new V3();
function segPt(a,b,c){const ab=_gwH.copy(b).sub(a),L2=ab.lengthSq();let t=L2>0?_gwI.copy(c).sub(a).dot(ab)/L2:0;t=clamp(t,0,1);return _gwI.copy(a).addScaledVector(ab,t).distanceTo(c);}
const _gwH=new V3(),_gwI=new V3();

// 3M9 (SA-6): 599 kg, 5.8 m, 335 mm; booster then ramjet (one long burn here), Mach 2.8, SARH on the 1S31 CW illumination
MSL['3M9']={ecc:.2,seek:'SARH',ign:0,burn:22,acc:72,cd:4.4e-5,maxG:19,gimbal:45*D2R,fuse:16,life:48,N:4,res:.6,rmin:4000,stop:300,search:0,smoke:.7,mass:599,aiR:24000,aiOff:20*D2R,trk:.5};
MOTOR['3M9']={b:5,s:20,f:.5};MDIA['3M9']=.335;SHAPE['3M9']={L:5.8,R:.1675,f:[[2.7,1.24,.95],[.3,1.52,.5]]};
{const d=MSL['3M9'],dia=MDIA['3M9'],S=Math.PI*dia*dia/4,dv=d.acc*d.burn,mbo=d.mass*Math.exp(-dv/2350),mp=d.mass-mbo,I=mp*2350,mo=MOTOR['3M9'];
  d.ph={S,dia,m0:d.mass,mp,mbo,tb:mo.b,ts:mo.s,Tb:mo.f*I/mo.b,Ts:(1-mo.f)*I/mo.s,mdB:mo.f*mp/mo.b,mdS:(1-mo.f)*mp/mo.s,cd0:2.38*d.cd*mbo/S,cnMax:.004*mbo/S};d.ph.cna=d.ph.cnMax/.38;d.burnT=mo.b+mo.s;}

// ---- weapons release for the A/G stores ----
function agTypes(P){return[...new Set(Object.values(P.load).filter(isAG))];}
function agPickle(w){const P=player,a=AGW[w];if(game.pickleCd>0)return;if(!game.arm){flash('MASTER ARM SIM',1200);return;}
  if(a.k==='bomb'){const p=P.release(w);if(!p){flash('NO '+SN[w],1000);return;}GND.drop(w,P,p);game.pickleCd=.3;sfx.click();return;}
  P.rk=P.rk||{};const st=Object.keys(P.load).filter(k=>P.load[k]===w);let fired=0;const per=a.cap>4?2:1;
  for(const k of st){if(P.rk[k]==null)P.rk[k]=a.cap;for(let i=0;i<per&&P.rk[k]>0;i++){P.rk[k]--;const m=P.stMesh[k],pos=m?P.pos.clone().add(m.position.clone().applyQuaternion(P.q)):P.pos.clone();
      setTimeout(()=>{if(P.alive)GND.fire(w,P,pos);},fired*45);fired++;}}
  if(!fired){flash('NO '+SN[w]+' LEFT',1000);return;}game.stats.shots+=fired;game.pickleCd=.25;sfx.click();}
function agLeft(P,w){const a=AGW[w];if(!a)return 0;if(a.k==='bomb')return P.count(w);P.rk=P.rk||{};let n=0;for(const k of Object.keys(P.load))if(P.load[k]===w)n+=P.rk[k]==null?a.cap:P.rk[k];return n;}

const NO_CCIP=new Set(['F-4E','MiG-21']);
/* ---- CCIP on every HUD: impact pipper with the bomb fall line from the flight path marker, rocket pipper with the range limit ---- */
function agHud(P,fs){const w=game.wsel;if(!AGW[w]||!P.alive)return;const a=AGW[w],ru=P.ac.cockpit==='fulcrum'||P.ac.pit==='flanker'||P.ac.pit==='flogger'||P.ac.pit==='fishbed'||P.ac.pit==='foxbat';
  // v215: no computed impact point on sights that never had one (F-4E AN/ASG-26 and the MiG-21bis ASP-PFD are fixed / manually depressed reticles):
  // the pilot gets a fixed pipper at a manual depression (bombs 140 mil, rockets 35 mil) and has to fly the planned dive, speed and release height
  if(NO_CCIP.has(P.type)&&(a.k==='bomb'||a.k==='pod')){const mil=a.k==='bomb'?140:35,sp=hb(0,-mil*.0573),k=KPX*D2R;hx.save();hx.lineWidth=1.6;
    if(sp){hx.beginPath();hx.arc(sp.x,sp.y,2,0,7);hx.fill();circ(sp.x,sp.y,k*1.43);for(let i=0;i<4;i++){const q=i*Math.PI/2,cq=Math.cos(q),sq=Math.sin(q);line(sp.x+cq*k*1.43,sp.y+sq*k*1.43,sp.x+cq*(k*1.43+6),sp.y+sq*(k*1.43+6));}}
    if(P.type!=='F-4E'){const p=hb(0,-11.6);if(p)txt((ru?'РУЧН ':'MAN ')+mil+(ru?' ТЫС · ':' MIL · ')+SN[w]+' '+agLeft(P,w)+(game.arm?'':(ru?' ОТКЛ':' SAFE')),p.x,p.y,'center');}
    hx.restore();return;}
  const c=GND.ccip(P,w),k=KPX*D2R;hx.save();hx.lineWidth=1.6;
  const lbl=(ru?(a.k==='bomb'?'БОМБ ':'НАР '):(a.k==='bomb'?'CCIP ':'RKT '))+SN[w]+' '+agLeft(P,w)+(game.arm?'':(ru?' ОТКЛ':' SAFE'));
  {const p=hb(0,-11.6);if(p)txt(lbl,p.x,p.y,'center');}
  if(!c){const p=hb(0,-10.6);if(p)txt(ru?'НЕТ РЕШ':'NO SOLN',p.x,p.y,'center');hx.restore();return;}
  let sp=proj(c.p);const fpm=projDir(_gwA.copy(P.vel).normalize());const lo=hb(0,-13.5);
  let clip=false;if(!sp||(lo&&sp.y>lo.y)){clip=true;if(fpm&&lo)sp={x:fpm.x,y:lo.y};}
  if(sp){if(clip)hx.setLineDash([4,4]);circ(sp.x,sp.y,k*1.6);hx.setLineDash([]);hx.beginPath();hx.arc(sp.x,sp.y,2,0,7);hx.fill();
    if(a.k==='bomb'&&fpm)line(fpm.x,fpm.y,sp.x,sp.y-k*1.6);
    if(a.k==='pod'){const ok=c.rng<=c.max;if(!ok&&blink){const p=hb(0,-9.6);if(p)txt(ru?'ДАЛЕКО':'OUT OF RNG',p.x,p.y,'center');}
      const p=hb(0,-9.6);if(p&&ok)txt((c.rng/1000).toFixed(1)+(ru?' КМ':' KM'),p.x,p.y,'center');}
    else{const p=hb(0,-9.6);if(p)txt((ru?'T ':'TOF ')+c.t.toFixed(1),p.x,p.y,'center');}}
  hx.restore();}

/* ============ F-16C Block 50 and the guided air-to-ground stores ============
   F-16C Block 50: F110-GE-129 (131.6 kN in afterburner, ~76 kN dry), APG-68(V)5, 9 g, heavier than the A (about 8,570 kg empty), more
   pylon plumbing: AIM-120 on 1-3 / 7-9, AGM-65 on 3, 4, 6, 7 (LAU-88 triple on 3 / 7), GBU-12 on 3, 4, 6, 7 (two per TER, slanted),
   targeting pod on the right chin station (5R).
   AGM-65D: 220 kg, 57 kg WDU-20/B shaped charge, imaging infrared, > 22 km, ~1,150 km/h. AGM-65F (Navy): 306 kg, 136 kg WDU-24/B, IIR.
   GBU-12 Paveway II: 230 kg Mk 82 with a nose laser seeker and bang-bang canards, CEP ~1 m when lased, 14.8 km.
   LITENING targeting pod: 208 kg, FLIR and CCD-TV with wide / narrow fields of view, laser designator and rangefinder, auto tracker. */
Object.assign(AGW,{
  'GBU-12': {k:'lgb',mass:230,L:3.27,R:.137,kd:3.0e-5,soft:45,hard:9,col:0x5e6a4a,band:0xd9b23a},
  'AGM-65D':{k:'agm',mass:220,L:2.49,R:.153,col:0xe6e3d8,soft:10,hard:3.2,dmg:150,dv:250,burn:3.6,kd:2.2e-5,maxG:15,range:22000,fov:[5,2.5],ir:1},
  'AGM-65F':{k:'agm',mass:306,L:2.49,R:.153,col:0xe6e3d8,soft:16,hard:4,dmg:190,dv:230,burn:3.6,kd:2.4e-5,maxG:14,range:22000,fov:[5,2.5],ir:1},
  'TGP':    {k:'tgp',mass:208,L:2.2,R:.19,col:0x8a9096}});
Object.assign(SN,{'GBU-12':'GBU12','AGM-65D':'65D','AGM-65F':'65F','TGP':'TGP'});
Object.assign(STORE_NAME,{'GBU-12':'GBU-12 Paveway II · laser','AGM-65D':'AGM-65D Maverick · IIR','AGM-65F':'AGM-65F Maverick · IIR, heavy','TGP':'LITENING targeting pod'});
// bombs keep the old shape; laser bombs get a seeker nose and canards, Mavericks a body with long-chord wings, the pod a turret nose
{const _b=buildAG;buildAG=function(kind){const a=AGW[kind];if(a.k==='bomb'||a.k==='pod')return _b(kind);
  const g=new THREE.Group(),w=SKIN(a.col,30),dk=SKIN(0x2a2d30,20),gl=SKIN(0x1c2a30,110),R=a.R,L=a.L;
  const cyl=(r0,r1,len,m,z,seg=16)=>{const c=new THREE.Mesh(new THREE.CylinderGeometry(r0,r1,len,seg),m);c.rotation.x=Math.PI/2;c.position.z=z;g.add(c);return c;};
  const fin=(span,chord,z,m,th=.012)=>{for(let i=0;i<4;i++){const f=new THREE.Mesh(new THREE.BoxGeometry(th,span,chord),m);const an=i*Math.PI/2+Math.PI/4;f.position.set(Math.cos(an)*(R+span/2-.02),Math.sin(an)*(R+span/2-.02),z);f.rotation.z=an-Math.PI/2;g.add(f);}};
  if(a.k==='lgb'){cyl(R,R,L*.42,w,.2);cyl(R*.2,R,L*.16,w,-L*.11);cyl(R,R*.5,L*.2,w,L*.4);cyl(R*.7,R*.2,L*.18,SKIN(0x8a8a82,40),-L*.3);
    const s=new THREE.Mesh(new THREE.SphereGeometry(R*.32,12,8),gl);s.position.z=-L*.4;g.add(s);fin(.16,.18,-L*.3,w,.01);fin(R*1.5,L*.16,L*.42,w);}
  else if(a.k==='agm'){cyl(R,R,L*.82,w,.05);const s=new THREE.Mesh(new THREE.SphereGeometry(R*.98,16,10,0,Math.PI*2,0,Math.PI/2),gl);s.rotation.x=-Math.PI/2;s.position.z=-L*.36;g.add(s);
    fin(.26,L*.42,.1,w);fin(.17,.2,L*.42,w);cyl(R*1.01,R*1.01,.04,SKIN(0xd9b23a,30),-L*.2);}
  else{cyl(R,R,L*.7,w,.25);const s=new THREE.Mesh(new THREE.SphereGeometry(R*1.05,16,12),SKIN(0x6d747a,40));s.position.z=-L*.42;g.add(s);
    const win=new THREE.Mesh(new THREE.CircleGeometry(R*.45,14),gl);win.position.set(0,-R*.5,-L*.42-R*.9);win.rotation.x=Math.PI*.6;g.add(win);cyl(R*.7,R,L*.12,w,L*.4);}
  return g;};}
const STORE_TPL_RESET=()=>{for(const k of['GBU-12','AGM-65D','AGM-65F','TGP'])if(STORE_TPL[k])delete STORE_TPL[k];};
PLANES.run('f16','L8518');
// the Hornet gets the Navy's Maverick, the laser bomb and its pod on the left fuselage station
{const H=STN['F-18C'];for(const k of['2','3','7','8'])if(H[k])H[k]=[...H[k],'AGM-65F','GBU-12'];if(H['4'])H['4']=[...H['4'],'TGP'];else H['4']=['TGP'];}

/* ---- AIM-120A / B everywhere the C goes, short names and loadout text ---- */
Object.assign(SN,{'AIM-120A':'120A','AIM-120B':'120B'});
Object.assign(WNAME,{'AIM-120A':'AMRAAM · 1991 · big fins','AIM-120B':'AMRAAM · 1994 · digital','AIM-120C':'AMRAAM · 1996 · clipped fins'});
MODERN_ONLY.add('AIM-120A');MODERN_ONLY.add('AIM-120B');
for(const ac of Object.keys(STN))for(const k of Object.keys(STN[ac])){const l=STN[ac][k],i=l.indexOf('AIM-120C');if(i>=0&&!l.includes('AIM-120A'))l.splice(i,0,'AIM-120A','AIM-120B');}
