  const M=clamp((vnoise(x/52000+7.1,z/52000-3.3)*.8+(x-25000)/85000)*1.1,0,1)+clamp((-x-60000)/40000+(-z-60000)/40000-.6,0,1)*.7;
  const rg=1-Math.abs(vnoise(x/15000+3.7,z/15000+9.2));v+=Math.min(M,1)*(rg*rg*2300+Math.max(0,h)*520);
  // the river valley along the old border
  const zr=6000+7000*Math.sin(x/23000+1.3)+vnoise(x/30000,4.4)*5000,dr=z-zr;v-=70*Math.exp(-dr*dr/6.8e6);
