        t._intT=(t._intT||0)-dt;if(t._intT>0)continue;t._intT=240;const b=nearestBase(1,t.pos.x,t.pos.z);if(!b||cd2(b.x,b.z,t.pos.x,t.pos.z)>160000)continue;
