    const st=this.st,day=this.clock().day;st.t+=dt/3600;if(this.clock().day!==day){this.applySeason(false);this.log('Day '+(this.clock().day+1)+' · '+this.clock().date+' · '+this.clock().sea.name.toLowerCase()+'.','');}
