   if(cd2(u.x,u.z,cp.x,cp.z)>24000&&cd2(t.x,t.z,cp.x,cp.z)>14000)return;const a=new V3(u.x,groundAt(u.x,u.z)+3,u.z),d=cd2(u.x,u.z,t.x,t.z),P=CAP2[u.k]||CAP2.ART;
