    c.font='700 9px "B612 Mono",monospace';c.fillStyle='rgba(220,235,240,.55)';c.textAlign='center';
    CFX.forEach((x,i)=>{if(st.hot.includes(i))return;const[sx,sy]=this.w2s(x,st.front[i]);if(this.mpp<900)c.fillText(String(i+1),sx,sy+14);});
