        c.save();c.translate(sx,sy);c.rotate(h);c.fillStyle=me?'#ffffff':j.side===1?'#ff5a4a':j.peer?'#7dffa0':'#5be1ff';c.beginPath();c.moveTo(0,-8);c.lineTo(5,6);c.lineTo(0,3);c.lineTo(-5,6);c.closePath();c.fill();c.restore();
