    const ps=this.podSpec(),e=this.podPos(P),l=this.spi.clone().sub(e).normalize(),u=P.up(new V3()),f=P.fwd(new V3());
    this.masked=l.dot(u)>.26||(l.dot(f)<-.5&&l.dot(u)>-.3);
