for(const era of Object.keys(CMS))CMS[era]['F-15E']=[60,60];
ECM_FIT['F-15E']={cold:{n:'ALQ-135(V) Band 1.5',jp:2,dec:.7,kg:0,cd:0,warm:25},modern:{n:'ALQ-250 EPAWSS',jp:2.6,dec:.84,kg:0,cd:0,warm:15}};
FOE['F-15E']='Su-27';NCTR_ID['F-15E']='F-15';CALLS['F-15E']='MUDHEN';ACROLE['F-15E']='US · DUAL-ROLE STRIKE · PILOT + WSO';FV['F-15E']=FV['F-15C'];
