    c.font=FS;c.fillStyle=GR;c.textAlign='center';c.textBaseline='middle';for(let p=-60;p<=60;p+=5){if(!p)continue;const y=py-p*K,w=p%10?14:30;c.setLineDash(p<0?[5,4]:[]);c.beginPath();c.moveTo(-w,y);c.lineTo(w,y);c.stroke();c.setLineDash([]);if(!(p%10)){c.fillText(String(Math.abs(p)),-w-14,y);c.fillText(String(Math.abs(p)),w+14,y);}}
