    {const a=-P.bank-Math.PI/2;c.beginPath();c.moveTo(cx+Math.cos(a)*100,cy+Math.sin(a)*100);c.lineTo(cx+Math.cos(a+.06)*90,cy+Math.sin(a+.06)*90);c.lineTo(cx+Math.cos(a-.06)*90,cy+Math.sin(a-.06)*90);c.closePath();c.fill();}
