  fixMode(P){const m=this.modes(P);if(!m.includes(this.mode))this.mode=m[0];},
  reset(){this.sel=null;this.list=[];this.known.clear();this.brief=[];this.mode='HAS';},
  rmax(P,w){const a=AGW[w];return 1000*(a.r0+a.r1*Math.max(0,P.pos.y)/1000+(P.vel.length()-250)*a.rv);},
