{const _cw=clearWorld;clearWorld=function(){_cw();CV.clear();TNK.clear();game.sub=null;};}
const swapAc=(ok,to,why)=>{if(ok.has(game.ac))return null;const old=game.ac;game.ac=to;setTimeout(()=>flash(why,3500),300);return old;};
const _s0=start0;
start0=async function(scen){
  if(scen==='SEAD'){const _sl=strikeLoad;strikeLoad=function(type,era){const c=getLoad(era,type);if(Object.values(c).some(s=>AGW[s]&&AGW[s].k==='arm'))return c;
      const L=(SEAD_LOAD[era]||SEAD_LOAD.cold)[type];return L?validLoad(type,era,Object.assign({},L)):_sl(type,era);};
    try{await _s0('STRIKE');}finally{strikeLoad=_sl;}
    if(!player||game.scen!=='STRIKE')return;game.sub='SEAD';seadSetup(player);return;}
  if(scen==='CVL'||scen==='CVA'||scen==='AAR'){const wing=game.wing,ss=game.sstart;game.wing=0;game.sstart='AIR';
    const old=scen==='AAR'?swapAc(new Set([...BOOM_AC,...PROBE_AC]),'F-16C','THIS JET HAS NO AIR-REFUELLING EQUIPMENT · FLYING THE F-16C'):swapAc(CV_AC,'F-18C','NOT CARRIER-CAPABLE · FLYING THE F/A-18C');
    try{await _s0('SOLO');}finally{game.wing=wing;game.sstart=ss;if(old)game.ac=old;}
    if(!player)return;game.sub=scen;{const r=$('#radio');if(r)r.innerHTML='';}
    if(scen==='AAR')aarSetup(player);else cvSetup(player,scen);return;}
  game.sub=null;return _s0(scen);};

function seadSetup(P){const hd=P.hdg*D2R,fx=Math.sin(hd),fz=-Math.cos(hd),rx=-fz,rz=fx,C=GND.center;
  // a second Kub battery covering the approach, offset to one side
  for(let tr=0;tr<12;tr++){const x=C.x-fx*(11000+tr*500)+rx*(6000-tr*900),z=C.z-fz*(11000+tr*500)+rz*(6000-tr*900),h=groundAt(x,z);if(h<15||h>1100)continue;
    const s=GND.add('SURN',1,x,z,P.hdg+180),tels=[];for(const[f,r]of[[220,0],[-220,0],[0,220],[0,-220]]){const t=GND.add('TEL',1,x+fx*f+rx*r,z+fz*f+rz*r,P.hdg+180);t.n=3;tels.push(t);}
    GND.sites.push({surn:s,tels,st:'search',det:0,trk:null,salvo:0,nextL:0,sweep:0,notchT:0,msl:[],lostT:0});break;}
  // the radars are the targets; the depot and the vehicles are scenery this time
  let n=0;for(const u of GND.units){const tg=u.kind==='SURN'||u.kind==='TOR';u.T=Object.assign({},u.T,{tgt:tg?1:0});if(tg)n++;}
  GND.targets=n;game.total=n;ARM.brief=GND.units.filter(u=>u.kind==='SURN'||u.kind==='TOR');
  const ar=Object.values(P.load).some(s=>AGW[s]&&AGW[s].k==='arm');if(ar)game.wsel=Object.values(P.load).find(s=>AGW[s]&&AGW[s].k==='arm');
  P.spawn(P.pos.x,6400,P.pos.z,P.hdg,250);ARM.mode=ARM.hts(P)?'HAD':'HAS';
  setTimeout(()=>flash(ar?'SEAD · KILL '+n+' RADARS · TWO SA-6 SITES AND A TOR · ENTER = HANDOFF, T = MODE':'SEAD · THIS JET HAS NO ANTI-RADIATION MISSILES · BOMB THE RADARS',5000),200);
  radio('Weasel lead: '+n+' radars briefed. HARM POS has the site locations; HAS / HAD finds them when they radiate.');}

function cvSetup(P,scen){CV.setup();P.hook=false;P.arOpen=false;
  if(scen==='CVL'){CV.spotCat(P,0);view='cockpit';radio(CV.name+' · cat 1 · run up to MIL to launch. After the shot: gear up, flaps up, come back for a Case I.');}
  else{// in the groove: 1.25 NM astern on the extended landing line, on glide slope, on speed
    const dl=2300,s=S_TD-dl,lx=LS.x+LD.x*s,lz=LS.z+LD.z*s,w=CV.world(lx,lz,{x:0,z:0});const lh=CV.lhdg(),V=(window.APP_KT[P.type]||138)/KT;
    P.spawn(w.x,CV.deckY+GH+Math.tan(GS*D2R)*dl,w.z,lh,V);P.vel.y=-((V-CV.spd*Math.cos(9*D2R))*Math.tan(GS*D2R));
    P.thr=(P.type==='F-18C'||P.type==='F-18E')?.6:.58;P.n=.8;sys.v.gear=1;sys.v.gearT=0;P._gc=undefined;P.gearPos=1;P.gearCmd=1;buildGearMesh(P);gearVis(P);P.flapCmd=P.flapPos=1;P.hook=true;
    const on=CV.onAoA(P);P.q.setFromEuler(_ge.set(on*D2R-Math.asin(clamp(-P.vel.y/V,-1,1)),-lh*D2R,0,'YXZ'));view='cockpit';
    radio(CV.name+' · Case I · you\'re in the groove, 1.2 miles. Gear, flaps and hook are down. Fly the ball.');}
  game.wsel=defaultWeapon('ir');}
// constant within this block: landing geometry repeated for the setup above
const LA=9*D2R,LS={x:2,z:166},LD={x:-Math.sin(LA),z:-Math.cos(LA)},S_TD=58,GS=3.5,CV_AC=window.CV_AC;

