/* ============ v132: station lists corrected to the loadout charts; F-14 targeting pod on 8A only ============ */
{const has=w=>!!(AGW[w]||(typeof MSL!=='undefined'&&MSL[w])||w==='TK'||w==='PTB');
  const U=(...ls)=>[...new Set(ls.flat())].filter(has);
  const rm=(ac,k,f)=>{if(STN[ac]&&STN[ac][k])STN[ac][k]=STN[ac][k].filter(t=>!f(t));};
  const isPod=t=>/^(LANTIRN|LITENING|SNIPER|ATFLIR|TGP)$/.test(t);
  // F-14A / F-14B: the only targeting pod station is the right glove, 8A
  for(const ac of['F-14A','F-14B']){if(!STN[ac])continue;
    for(const k of Object.keys(STN[ac]))rm(ac,k,isPod);
    STN[ac]['8A']=U(STN[ac]['8A'],['LANTIRN']);}
  if(typeof STRIKE_LOAD!=='undefined'&&STRIKE_LOAD['F-14B']&&STRIKE_LOAD['F-14B']['8B']==='LANTIRN'){delete STRIKE_LOAD['F-14B']['8B'];STRIKE_LOAD['F-14B']['8A']='LANTIRN';}
  // F/A-18C: fuselage stations 4 / 6 carry missiles (4 also the FLIR pod), bombs go on 2 / 3 / 5 / 7 / 8
  if(STN['F-18C']){const bombs=t=>!/^(AIM-|AGM-88)/.test(t)&&t!=='TK'&&!isPod(t);
    for(const k of Object.keys(STN['F-18C'])){if(/^[46]/.test(k))rm('F-18C',k,bombs);}
    STN['F-18C']['5']=U(STN['F-18C']['5'],['TK','Mk-82','Mk-82AIR','Mk-20','GBU-12','GBU-16','GBU-10','GBU-24']);}
  // F-4E: Sidewinders on the inboard pylons only, outboard 1 / 9 take bombs and Shrikes, centreline takes a tank or bombs
  if(STN['F-4E']){const aam9=t=>/^AIM-9/.test(t);
    const bombs=U(['Mk-82','Mk-83','Mk-84','Mk-20','CBU-87','GBU-10','GBU-12','GBU-24','AGM-45A','Mk-82AIR']);
    for(const k of['1','9']){rm('F-4E',k,aam9);STN['F-4E'][k]=U(STN['F-4E'][k],['TK'],bombs);}
    for(const k of Object.keys(STN['F-4E']))if(/^[28]/.test(k))STN['F-4E'][k]=U(STN['F-4E'][k],F4W);
    STN['F-4E']['C']=U(STN['F-4E']['C'],['PTB'],['Mk-82','Mk-83','Mk-84','Mk-20','GBU-10','GBU-12']);
    for(const era of['cold','modern','guns'])if(LOAD[era]&&LOAD[era]['F-4E']){const o=LOAD[era]['F-4E'];
      for(const[o1,i]of[['1','2'],['9','8']])if(o[o1]&&aam9(o[o1])){if(!o[i]||o[i]==='TK')o[i]=o[o1];delete o[o1];}}
    if(STRIKE_LOAD['F-4E']){const o=STRIKE_LOAD['F-4E'];for(const k of['1','9'])if(o[k]&&aam9(o[k]))delete o[k];}}
  // F-16C Block 50: bombs and pods on 3 / 4 / 6 / 7, wingtips and 2 / 8 stay missile stations
  if(STN['F-16C']){const A=['GBU-10','GBU-12','GBU-24','GBU-31','GBU-38','Mk-82','Mk-82AIR','Mk-84','CBU-87','CBU-97','CBU-103','CBU-105','AGM-154A','AGM-88B','AGM-88C'];
    for(const k of['3','4','6','7'])STN['F-16C'][k]=U(STN['F-16C'][k],A);}
  // F-15E: bombs on 2 / 5 / 8 and the CFT stations, pod on the TP station
  if(STN['F-15E']){const A=['Mk-82','Mk-84','Mk-20','GBU-10','GBU-12','GBU-24','GBU-31','GBU-38','CBU-87','CBU-97','CBU-103','CBU-105','AGM-154A'];
    for(const k of['2','8'])STN['F-15E'][k]=U(STN['F-15E'][k],A);
    STN['F-15E']['5']=U(STN['F-15E']['5'],A,['GBU-28']);
    for(const k of['LC1','LC2','LC3','RC1','RC2','RC3'])STN['F-15E'][k]=U(STN['F-15E'][k],A);
    const small=A.filter(t=>!/^(Mk-84|GBU-10|GBU-24|GBU-31|AGM-154A)$/.test(t));
    for(const k of['LO1','LO2','LO3','RO1','RO2','RO3'])STN['F-15E'][k]=U(STN['F-15E'][k],small);}
  // hangar front view: the tank and corner stations are spread out so every one can be seen and picked (F fore / C centre / A aft read left to right)
  if(AC['F-15E']){const v={};for(const[k,p]of Object.entries(AC['F-15E'].st))v[k]=p.slice();
    const fan=(sd,p,o)=>{o.forEach((r,i)=>{v[p+(i+1)]=[sd*(1.55+.4*i),r,0];});};
    for(const[sd,i,o,c,a]of[[-1,'LC','LO','3C','4C'],[1,'RC','RO','7C','6C']]){
      [1,2,3].forEach((n,j)=>{v[i+n]=[sd*(1.55+.4*j),-.85,0];v[o+n]=[sd*(1.55+.4*j),-1.38,0];});
      v[c]=[sd*.95,-.9,0];v[a]=[sd*.95,-1.38,0];}
    AC['F-15E'].vst=v;}
  window.validLoadsCheck=1;}
