{const _sc=CAMP.sortieCheck;CAMP.sortieCheck=function(dt){_sc.call(this,dt);const P=player;
  if(P&&P.alive&&this.sortie&&!game.over&&CV.on&&CV.trap&&CV.trap.done&&CV.trap.doneT>2.5){
    if(net.on){flash('TRAPPED ABOARD '+CV.name+' · REARMED AND REFUELED',3000);this.sortie.air=false;this.rearm();CV.spotCat(P,0);}
    else{game.over=true;game.result='TRAPPED ABOARD '+CV.name;game.endT=2.5;flash('SORTIE COMPLETE · '+CV.name,2500);}}};}
// the strip shows the ship while it is up
{const _st=CAMP.strip;CAMP.strip=function(){_st.call(this);const el=$('#cmStrip'),P=player;if(el&&!el.hidden&&CV.on&&P)el.innerHTML+='<span>·</span>CVN '+String(Math.round(brgTo(P.pos.x,P.pos.z,CV.pos.x,CV.pos.z))).padStart(3,'0')+'° '+Math.round(cd2(P.pos.x,P.pos.z,CV.pos.x,CV.pos.z)/NM)+' NM';};}
