  const P=player&&player.alive?player:null,cands=st.units.filter(u=>!u.dead&&u.s===0&&hot.includes(u.i));if(!cands.length)return;
  if(P)cands.sort((a,b)=>cd2(a.x,a.z,P.pos.x,P.pos.z)-cd2(b.x,b.z,P.pos.x,P.pos.z));const u=P&&Math.random()<.6?cands[0]:cpick(cands);
  let b=null,bd=1e12;for(const q of this.bases(1)){if(q.pool<2||q.dmg>75)continue;const d=cd2(q.x,q.z,u.x,u.z);if(d<bd){bd=d;b=q;}}if(!b||bd>190000)return;
  const f=this.launch(1,'STK',b.id,2,{x:u.x,z:u.z,tu:u.id});if(!f)return;{const e=this.launch(1,'ESC',b.id,2,{x:u.x,z:u.z})||(this.bases(1).filter(q=>q.id!==b.id&&q.pool>=2&&q.dmg<=75).map(q=>this.launch(1,'ESC',q.id,2,{x:u.x,z:u.z})).find(Boolean));if(e)escortBind(e,f);}
