  for(const b of CBASE){let h=0;for(const [dx,dz] of [[0,0],[600,0],[-600,0],[0,1500],[0,-1500]])h+=cmpRaw(b.x+dx,b.z+dz);b.H=clamp(h/5,35,640);}
