{const _cs=CAMP.cvSite;CAMP.cvSite=function(){if(!ROT)return _cs.apply(this,arguments);const tm=CV._tm,sea=(x,z)=>tm(x,z)<-15;
  for(let x=-112000;x>=-150000;x-=2000)for(let z0=80000;z0>=20000;z0-=4000){let ok=true;
    for(let s=-4000;s<=CV.legLen+3000&&ok;s+=1500)for(const o of[-3500,0,3500])if(!sea(x+o,z0-s)){ok=false;break;}if(ok)return{x,z:z0,h:0};}
  for(let x=112000;x<=150000;x+=2000)for(let z0=80000;z0>=20000;z0-=4000){let ok=true;
    for(let s=-4000;s<=CV.legLen+3000&&ok;s+=1500)for(const o of[-3500,0,3500])if(!sea(x+o,z0-s)){ok=false;break;}if(ok)return{x,z:z0,h:0};}
  return _cs.apply(this,arguments);};}

// one save per team, so switching sides never blocks a sortie or throws away the other war
const KEY=t=>t==='RED'?'viper.camp.red':'viper.camp';
CAMP.save=function(){if(!this.st||this.client)return;try{localStorage.setItem(KEY(this.st.team||'BLUE'),JSON.stringify(this.st));}catch(e){}};
CAMP.load=function(){try{const o=JSON.parse(localStorage.getItem(KEY(game.team))||'null');if(o&&(o.v===3||o.v===4)&&Array.isArray(o.units)){if(!o.team)o.team='BLUE';if(o.team!==game.team)return false;this.st=o;this.ensureV4();rotSync();return true;}}catch(e){}return false;};
