  const it=[['СДУ',ok(dm.fcs)&&P.hp>30],['НАВ',true],['СУО',P.hp>20],['РЭБ',!!(P.ecm)],['РЛС',radar.on()],['СВЯЗЬ',P.hp>15],['ОЛС',!!P.ac.irst],['ГИДР',ok(dm.hyd)],['ЭЛЕКТР',ok(dm.elec)],['ДВИГ',P.hp>25]];
