// ===== v186: Su-27SM MFIs — English / Russian legends from the HUD-language setting; working target lock from the MFI keys =====
try{
const SMEN={'АВ.СБР':'JETT','АЭР':'AFLD','БВБ':'ACM','ВАР':'VVI','ВКЛ':'ON','ВООРУЖЕНИЕ':'STORES','ВЫБРАНО':'SEL','ВЫКЛ':'OFF','ГИДР':'HYD','Д':'R','ДАЛ':'RNG','ДВ1':'ENG1','ДВ2':'ENG2',
  'ДВИГ':'ENG','ДВИГАТЕЛИ':'ENGINES','ДО':'CHAFF','ЗАХВ':'LOCK','ЗАХВАТ':'STT','ИЛС':'ILS','ИСТ':'TAS','КГ':'KG','КМ':'KM','КУРС':'HDG','ЛЕВ':'LEFT','ЛТЦ':'FLARE','МАСШ':'SCALE','МИН':'MIN',
  'НАВ':'NAV','ОБ':'RPM','ОБЗ':'RWS','ОБЗОР':'RWS','ОЛС':'IRST','ОСТАТОК':'ENDUR','ПР':'IAS','ПРАВ':'RIGHT','ПРОВ':'TEST','ПУШ':'GUN','ПУШКА':'GUN','Р':'R','РАСХОД':'FLOW','РЛ':'SARH','РЛС':'RDR',
  'РЭБ':'ECM','СБР':'DROP','СВЯЗЬ':'COMM','СДУ':'FCS','СИСТ':'SYS','СИСТЕМЫ':'SYSTEMS','СЛЕД':'NEXT','СНП':'TWS','СНП-2':'TWS-2','СУО':'SMS','ТВС':'TV','ТГС':'IR','ТОПЛ':'FUEL','ТОПЛИВО':'FUEL',
  'ФОРСАЖ':'AB','ЦУ':'DESIG','Ч':'H','ЭЛЕКТР':'ELEC','ЯРК+':'BRT+','ЯРК−':'BRT−','ЯРК':'BRT','ЦЕЛЬ':'TGT','ЦЕЛЬ+':'TGT+','ТВ':'TV'};
const smEN=()=>typeof SET!=='undefined'&&SET.hudlang==='EN';
const REV={};for(const [k,v] of Object.entries(SM_ST))REV[v]=k;
window.smTr=s=>{if(!smEN()||typeof s!=='string'||!/[А-Яа-яЁё]/.test(s))return s;
  return s.replace(/[А-Яа-яЁё][А-Яа-яЁё0-9.\-+−]*/g,w=>SMEN[w]??REV[w]??(SMEN[w.replace(/[+−]$/,'')]!=null?SMEN[w.replace(/[+−]$/,'')]+w.slice(-1):w));};
{const _t=smTxt;smTxt=function(c,s,...r){return _t(c,smTr(s),...r);};}
{const _l=smLabel;smLabel=function(...a){return smTr(_l(...a));};}
// ---- lock: A/G seeker (Kh-29 / KAB) or anti-radiation target, else radar: cursor contact, TWS bug, or the nearest track ----
window.smLock=function(){const P=player;if(!P||!P.alive)return;const a=AGW[game.wsel];
  if(a&&a.k==='arm'&&typeof ARM!=='undefined'){ARM.next();return;}
  if(SNS.active()){SNS.tms();return;}
  if(a){flash(smTr('НЕТ ЦУ'),900);return;}
  if(!radar.on()){flash(smEN()?'RADAR OFF':'РЛС ВЫКЛ',900);return;}
  if(radar.mode==='STT')return;
  const b=radar.bug;if(b&&b.alive){const g=radar.ang(b.pos);if(radar.detect(b,g)&&g.off<radar.gimbal()){radar.stt(b);return;}}
  radar.designate();if(radar.mode==='STT')return;
  const was=radar.mode;if(was==='TWS'){const list=[...radar.tracks.entries()].filter(([j])=>j.alive).sort((x,y)=>x[1].d-y[1].d);
    for(const [j] of list){const g=radar.ang(j.pos);if(radar.detect(j,g)&&g.off<radar.gimbal()){radar.stt(j);return;}}}
  else radar.next();
  if(radar.mode!=='STT')flash(smEN()?'NO TARGET':'НЕТ ЦЕЛИ',900);};
window.smNext=function(){const a=AGW[game.wsel];if(a&&a.k==='arm'&&typeof ARM!=='undefined'){ARM.next();return;}
  if(radar.mode==='TWS'||radar.mode==='STT'){if(radar.mode==='STT'){radar.next();return;}radar.next();return;}
  const list=[...radar.tracks.entries()].filter(([j])=>j.alive).sort((x,y)=>x[1].d-y[1].d);if(!list.length){flash(smEN()?'NO TRACKS':'НЕТ ЦЕЛЕЙ',800);return;}
  const i=list.findIndex(([j])=>j===radar.bug);radar.bug=list[(i+1)%list.length][0];radar.bugMan=true;sfx.click();};
{const _b=smBottom;smBottom=function(pg){const r=_b(pg);
  if(pg==='RDR'){r[5]=['ЗАХВ',()=>smLock(),()=>radar.mode==='STT'||!!(SNS.mav&&SNS.mav.alive)];}
  if(pg==='SMS'){r[4]=['ЗАХВ',()=>smLock(),()=>radar.mode==='STT'||!!(SNS.mav&&SNS.mav.alive)];r[5]=['ЦЕЛЬ+',()=>smNext()];}
  return r;};}
// right-hand keys of the side MFIs on the RADAR page: TGT+ / LOCK / DROP
const SM_RSIDE=window.SM_RSIDE={RDR:['ЦЕЛЬ+','ЗАХВ','СБР','',''],SMS:['ЦЕЛЬ+','ЗАХВ','','','']};window.SMEN=SMEN;
{const _l=smLabel;smLabel=function(k,sd,i){if(sd==='R'){const r=SM_RSIDE[SMM[k]&&SMM[k].pg];return smTr(r?r[i]||'':'');}return _l(k,sd,i);};}
{const _p=smPress;smPress=function(k,sd,i){if(sd==='R'){const r=SM_RSIDE[SMM[k]&&SMM[k].pg],a=r&&r[i];if(a==='ЦЕЛЬ+')smNext();else if(a==='ЗАХВ')smLock();else if(a==='СБР')radar.drop();return;}return _p(k,sd,i);};}
// draw the right-hand legends too
{const _s=smScreen;smScreen=function(key,cv){_s(key,cv);const S=SMM[key],G=window.SMG&&SMG[key];if(!G||S.off||key==='C')return;const r=SM_RSIDE[S.pg];if(!r)return;
  const c=cv.getContext('2d'),W=cv.width,H=cv.height,ty=i=>H/2-((i-(G.nS-1)/2)*(G.h/G.nS)*.95)/G.h*H;
  for(let i=0;i<G.nS;i++)if(r[i])smTxt(c,r[i],W-26,ty(i),r[i]==='ЗАХВ'&&radar.mode==='STT'?'#ffd27a':'#9fe8c0',11);};}
}catch(e){console.warn('v186 Su-27SM MFI',e);}

// ===== v187: Su-27SM air-to-ground radar (N001VE ground-map / GMT / sea / ranging), TV page for the weapon seeker, A/G HUD cues =====
// After the Su-30 CWS documentation: A/G master mode → radar scan changes from BVR to GND; the TV weapon's seeker video is shown on an MFI
