SM_TOP.L[SM_TOP.L.indexOf('ENG')]='TV';SM_TOP.R[SM_TOP.R.indexOf('ENG')]='TV';SM_PGN.TV='ТВ';
{const _p=smPress;smPress=function(k,sd,i){if(sd==='T'){const p=SM_TOP[k][i];if(p==='TV'||p==='RDR')SMM.agf=p;}return _p(k,sd,i);};}
// ---- A/G radar: the Western jets' engine, with the N001VE mode set ----
const AGR=window.V121.AGR;
{const _a=AGR.active.bind(AGR);AGR.active=function(){const P=player;if(P&&SMX(P.type))return !!(P.alive&&game.active&&game.wsel&&AGW[game.wsel]&&radar.on()&&radar.sensor==='RDR'&&SMM.agf!=='TV'&&smShows('RDR'));return _a();};}
{const _a=AGR.avail.bind(AGR);AGR.avail=function(P){return (P&&SMX(P.type))||_a(P);};}
{const _m=AGR.modesFor.bind(AGR);AGR.modesFor=function(P){return P&&SMX(P.type)?['GM','GMT','SEA','AGR']:_m(P);};}
