  const tl=EN()?'TV':'ТВ',lk=SNS.mav&&SNS.mav.alive;c.strokeRect(ox+s-52,oy+s-24,44,18);smTxt(c,tl,ox+s-30,oy+s-15,'#7dffa0',12);
