  for(const e of this.list.slice(0,10)){if(this.sel&&e.u===this.sel.u)continue;const s=proj(new V3().copy(e.u.pos).setY(e.u.pos.y+3));if(s)diamond(s.x,s.y,k*.45);}
  if(this.sel){const s=proj(new V3().copy(this.sel.pos).setY(this.sel.pos.y+3));if(s){circ(s.x,s.y,k*.9);hx.beginPath();hx.arc(s.x,s.y,1.8,0,7);hx.fill();}}
