/* ===== v205: Su-27SM Kh-31P: pick emitters one at a time. Enter locks the emitter under the designator square, Tab steps the square
   left-to-right across the emitters in the seeker field (and locks the one it lands on), U drops, and a click on an emitter symbol on the HUD
   locks that emitter. ===== */
{const smArm=()=>player&&player.alive&&SMX(player.type)&&window.ARM&&ARM.w();
 const pick=u=>{const P=player;ARM.sel={u,pos:u.pos.clone(),src:ARM.mode};const v=u.pos.clone().sub(P.pos).applyQuaternion(qInv(P.q));
   if(window.SMTD&&v.z<0){SMTD.az=Math.atan(v.x/-v.z)*R2D;SMTD.el=Math.atan(v.y/-v.z)*R2D;}sfx.click();flash((SET.hudlang==='EN'?'LOCK · ':'ЗАХВАТ · ')+ARM.code(u),900);};
 const sorted=()=>{const P=player;ARM.fixMode(P);ARM.scan(P);return ARM.list.map(e=>{const v=e.u.pos.clone().sub(P.pos).applyQuaternion(qInv(P.q));return{e,az:Math.atan2(v.x,-v.z)};}).sort((a,b)=>a.az-b.az).map(o=>o.e);};
 addEventListener('keydown',e=>{if(!smArm()||!game.running||!$('#menu').hidden||e.repeat||e.ctrlKey||e.metaKey||e.altKey)return;
   if(e.code==='Tab'){e.preventDefault();e.stopImmediatePropagation();const l=sorted();if(!l.length){flash(SET.hudlang==='EN'?'NO EMITTERS IN THE SEEKER FIELD':'НЕТ РИЦ',1000);return;}
     const i=ARM.sel?l.findIndex(x=>x.u===ARM.sel.u):-1;pick(l[(i+1)%l.length].u);}
   else if(e.code==='Enter'||e.code==='NumpadEnter'){e.preventDefault();e.stopImmediatePropagation();if(window.smTdLock)smTdLock();}
   else if(e.code==='KeyU'){e.preventDefault();e.stopImmediatePropagation();ARM.sel=null;sfx.click();}},true);
 $('#gl').addEventListener('pointerdown',e=>{if(!smArm()||!game.running||e.button!==0)return;const l=sorted(),r=hud.getBoundingClientRect(),sx=1;let best=null,bd=28;
   for(const x of l){const p=proj(x.u.pos);if(!p)continue;const d=Math.hypot(p.x-(e.clientX-r.left)*sx,p.y-(e.clientY-r.top)*sx);if(d<bd){bd=d;best=x;}}
   if(best){e.stopImmediatePropagation();pick(best.u);}},true);}
