for(const k of['L','R']){mkState('35'+k,k==='L'?'RDR':'VSD',k==='L'?'SPO':'SMS');build({key:'35'+k,g:G35,X:(k==='L'?-1:1)*.2,Y:-.068,w:.366,h:.25,cw:878,ch:600,nT:12,nS:8,name:'МФИ-35 '+(k==='L'?'1':'2')});}
