const GMP=new THREE.Group();GMP.position.set(-.43,-.12,.2);GMP.rotation.set(-.55,.35,0);GMP.scale.setScalar(1.15);window.V226={GMP};G35.add(GMP);mkState('MP','KIS','VSD');
